    /// Test helper converting a run request into one step request.
    /// It adds one uncached whole-request projection, so assertions inspect the
    /// actual sidecar frame rather than a test-built approximation.
    /// Visible text of an upstream `input` item, independent of wire shape.
    /// Assert what the model receives, not provider-specific envelope details.
    fn item_text(item: &Value) -> String {
        match &item["content"] {
            Value::String(text) => text.clone(),
            Value::Array(parts) => parts
                .iter()
                .filter_map(|part| part["text"].as_str())
                .collect::<Vec<_>>()
                .join(""),
            _ => String::new(),
        }
    }

    /// Whether an item has the specified role and exact visible text.
    fn has_message(items: &[Value], role: &str, text: &str) -> bool {
        items
            .iter()
            .any(|item| item["role"] == role && item_text(item) == text)
    }

