    /// Plan approval moves the level in the middle of a turn. The run and every
    /// descendant read the shared cell, so the switch reaches children spawned
    /// before it as well as after it, while the snapshot still records where the
    /// run began.
    #[test]
    fn the_live_level_reaches_the_run_and_its_children() {
        let mut parent = run_request(ProviderFamily::OpenaiResponses);
        parent.security_level = SecurityLevel::Plan;
        let cell = Arc::new(crate::model::LiveSecurityLevel::new(SecurityLevel::Plan));
        parent.live_security_level = Some(Arc::clone(&cell));
        assert_eq!(parent.effective_security_level(), SecurityLevel::Plan);

        let before = agent_child_template(&parent);
        assert_eq!(before.effective_security_level(), SecurityLevel::Plan);

        cell.set(SecurityLevel::AllowEdits);
        assert_eq!(parent.effective_security_level(), SecurityLevel::AllowEdits);
        assert_eq!(parent.security_level, SecurityLevel::Plan);

        let after = agent_child_template(&parent);
        assert_eq!(after.security_level, SecurityLevel::AllowEdits);
        assert_eq!(after.effective_security_level(), SecurityLevel::AllowEdits);
        assert_eq!(before.effective_security_level(), SecurityLevel::AllowEdits);
    }

    /// The section is assembled at the wire layer, so it has to appear and
    /// disappear with the level in force for this step — not the one the run
    /// started with — and a child must never receive the workflow that tells it
    /// to write the plan and leave the mode.
    #[test]
    fn the_plan_mode_section_follows_the_live_level_and_the_agent_depth() {
        let mut request = run_request(ProviderFamily::OpenaiResponses);
        let main_section = request
            .prompt_profile
            .text(crate::prompt_profile::PromptKey::SystemPlanMode);
        let child_section = request
            .prompt_profile
            .text(crate::prompt_profile::PromptKey::SystemPlanModeSubagent);

        for level in [
            SecurityLevel::RequestApproval,
            SecurityLevel::AllowEdits,
            SecurityLevel::FullAccess,
        ] {
            request.security_level = level;
            for depth in [0, 1] {
                request.subagent_depth = depth;
                let system = crate::aisdk::step::combined_system_prompt(&request);
                assert!(
                    !system.contains("Plan mode is active"),
                    "{level:?} depth {depth}"
                );
            }
        }

        request.security_level = SecurityLevel::Plan;
        request.subagent_depth = 0;
        let system = crate::aisdk::step::combined_system_prompt(&request);
        assert!(system.contains(main_section.trim()));
        assert!(!system.contains(child_section.trim()));

        request.subagent_depth = 1;
        let system = crate::aisdk::step::combined_system_prompt(&request);
        assert!(system.contains(child_section.trim()));
        assert!(!system.contains("## Plan workflow"));

        // Approval lands in the cell, and the very next step must go out without
        // the section even though the run started in plan mode.
        request.subagent_depth = 0;
        let cell = Arc::new(crate::model::LiveSecurityLevel::new(SecurityLevel::Plan));
        request.live_security_level = Some(Arc::clone(&cell));
        assert!(crate::aisdk::step::combined_system_prompt(&request).contains("Plan mode is active"));
        cell.set(SecurityLevel::AllowEdits);
        assert!(!crate::aisdk::step::combined_system_prompt(&request).contains("Plan mode is active"));
    }

    /// A run loop pointed at `address` and started in `level`, with the three
    /// plan tools removed from `enabled_tools`: whatever the model is allowed to
    /// call here was derived by the host from the level, not enabled by anyone.
    fn plan_mode_loop_fixture(
        address: std::net::SocketAddr,
        directory: &tempfile::TempDir,
        level: SecurityLevel,
    ) -> (
        AppState,
        RunModelRequest,
        Arc<crate::model::LiveSecurityLevel>,
        Arc<crate::conversation_store::ConversationStore>,
    ) {
        let state = AppState::default();
        let mut request = loop_request_for(address, directory.path());
        request.security_level = level;
        request
            .enabled_tools
            .retain(|name| !crate::plan_mode::is_plan_mode_tool_name(name));
        let cell = state.live_security_level_for_run(&request.conversation_id, level);
        request.live_security_level = Some(Arc::clone(&cell));

        let mut document = catalog::default_document(directory.path());
        document.workspaces[0].id = request.workspace_id.clone();
        document.workspaces[0].conversations[0].id = request.conversation_id.clone();
        document.workspaces[0].conversations[0].settings.security_level = level;
        let anchor = directory.path().join("document.v1.json");
        state
            .document_store
            .acquire_process_authority(&anchor)
            .unwrap();
        state.document_store.commit(&anchor, document.clone()).unwrap();
        let store = crate::conversations::store(&anchor).unwrap();
        store
            .put_conversation(
                &request.workspace_id,
                &document.workspaces[0].conversations[0],
            )
            .unwrap();
        (state, request, cell, store)
    }

    /// Answers the first plan card the run raises and hands the card back, so a
    /// test can assert on what the user was actually shown.
    fn answer_first_plan_card(
        state: &AppState,
        decision: crate::tool_prompt::ToolPromptDecision,
        feedback: Option<&str>,
    ) -> thread::JoinHandle<crate::tool_prompt::PendingToolPrompt> {
        let answering = state.clone();
        let feedback = feedback.map(str::to_owned);
        thread::spawn(move || {
            let deadline = Instant::now() + Duration::from_secs(30);
            while Instant::now() < deadline {
                if let Some((_, card)) =
                    answering.tool_prompts().all_pending_cards().into_iter().next()
                {
                    if answering
                        .tool_prompts()
                        .resolve(&card.prompt_id, decision, feedback.clone())
                        .is_ok()
                    {
                        return card;
                    }
                }
                thread::sleep(Duration::from_millis(5));
            }
            panic!("no plan card was ever announced");
        })
    }

    fn function_call_response(call_id: &str, name: &str, arguments: Value) -> Value {
        json!({
            "model": "model-test",
            "status": "completed",
            "output": [{
                "type":"function_call",
                "status":"completed",
                "call_id": call_id,
                "name": name,
                "arguments": serde_json::to_string(&arguments).unwrap()
            }],
            "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}
        })
    }

    fn tool_output<'a>(response: &'a RunModelResponse, tool: &str) -> &'a ToolResult {
        response
            .contexts
            .iter()
            .find_map(|context| match context {
                ContextItem::Tool {
                    tool_name, result, ..
                } if tool_name == tool => Some(result),
                _ => None,
            })
            .unwrap_or_else(|| panic!("{tool} never produced a result"))
    }

    /// The whole plan-mode round trip through the run loop: the two tools that
    /// exist only in plan mode are admitted without being enabled, the card
    /// carries the plan's own title, and "always" is the accept-edits answer —
    /// it moves the live cell and the persisted setting, and the approved
    /// markdown comes back to the model so it can start implementing.
    #[test]
    fn an_approved_plan_leaves_plan_mode_and_returns_the_plan_to_the_model() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(
            listener,
            vec![
                function_call_response(
                    "call-plan-write",
                    "plan",
                    json!({"action":"write","content":"# Ship the parser\n\nRewrite the tokenizer."}),
                ),
                function_call_response("call-exit", "exit_plan_mode", json!({})),
                responses_text_output("done"),
            ],
        );

        let directory = tempfile::tempdir().unwrap();
        let (state, request, cell, store) =
            plan_mode_loop_fixture(address, &directory, SecurityLevel::Plan);
        let conversation_id = request.conversation_id.clone();
        let answering =
            answer_first_plan_card(&state, crate::tool_prompt::ToolPromptDecision::AllowAlways, None);

        let response = run_model(request, &state, &discard_event, &|_, _, _| {
            panic!("a plan tool must not go through the ordinary approval gate")
        })
        .unwrap();
        server.join().unwrap();
        let card = answering.join().unwrap();

        assert_eq!(card.kind, crate::tool_prompt::PromptKind::PlanExit);
        assert_eq!(card.tool_name, "exit_plan_mode");
        assert_eq!(card.summary, "Ship the parser");
        assert!(!card.allow_always_offered);
        assert!(card.mandatory);

        let written = tool_output(&response, "plan");
        assert!(written.success, "{}", written.output);
        assert!(written.output.starts_with("Plan saved ("), "{}", written.output);

        let exited = tool_output(&response, "exit_plan_mode");
        assert!(exited.success, "{}", exited.output);
        assert!(exited.output.contains("Permission mode is now accept edits"));
        assert!(exited.output.contains("## Approved Plan:\n# Ship the parser"));

        assert_eq!(cell.get(), SecurityLevel::AllowEdits);
        assert_eq!(
            store
                .conversation(&conversation_id)
                .unwrap()
                .unwrap()
                .settings
                .security_level,
            SecurityLevel::AllowEdits
        );
        let plan = store.conversation_plan(&conversation_id).unwrap().unwrap();
        assert_eq!(plan.status, crate::model::PlanStatus::Approved);
        assert!(plan.markdown.starts_with("# Ship the parser"));
    }

    /// A refusal is not a broken tool: the call succeeded, the answer was "not
    /// yet", and what the user typed is the only thing that tells the model what
    /// to change. The conversation stays in plan mode.
    #[test]
    fn a_denied_plan_stays_in_plan_mode_and_returns_the_users_words() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(
            listener,
            vec![
                function_call_response(
                    "call-plan-write",
                    "plan",
                    json!({"action":"write","content":"# Ship the parser"}),
                ),
                function_call_response("call-exit", "exit_plan_mode", json!({})),
                responses_text_output("understood"),
            ],
        );

        let directory = tempfile::tempdir().unwrap();
        let (state, request, cell, store) =
            plan_mode_loop_fixture(address, &directory, SecurityLevel::Plan);
        let conversation_id = request.conversation_id.clone();
        let answering = answer_first_plan_card(
            &state,
            crate::tool_prompt::ToolPromptDecision::Deny,
            Some("cover the migration too"),
        );

        let response = run_model(request, &state, &discard_event, &|_, _, _| {
            panic!("a plan tool must not go through the ordinary approval gate")
        })
        .unwrap();
        server.join().unwrap();
        answering.join().unwrap();

        let exited = tool_output(&response, "exit_plan_mode");
        assert!(exited.success, "{}", exited.output);
        assert!(exited.output.contains("cover the migration too"));
        assert!(exited.output.contains("chose to stay in plan mode"));

        assert_eq!(cell.get(), SecurityLevel::Plan);
        assert_eq!(
            store
                .conversation(&conversation_id)
                .unwrap()
                .unwrap()
                .settings
                .security_level,
            SecurityLevel::Plan
        );
        assert_eq!(
            store.conversation_plan(&conversation_id).unwrap().unwrap().status,
            crate::model::PlanStatus::Rejected
        );
    }

    /// Outside plan mode the derived tool is the other one, and a single "allow
    /// once" is what enters the mode — there is no "always" to accumulate.
    #[test]
    fn entering_plan_mode_takes_one_allow_and_moves_the_conversation() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(
            listener,
            vec![
                function_call_response("call-enter", "enter_plan_mode", json!({})),
                responses_text_output("planning"),
            ],
        );

        let directory = tempfile::tempdir().unwrap();
        let (state, request, cell, store) =
            plan_mode_loop_fixture(address, &directory, SecurityLevel::RequestApproval);
        let conversation_id = request.conversation_id.clone();
        let answering =
            answer_first_plan_card(&state, crate::tool_prompt::ToolPromptDecision::AllowOnce, None);

        let response = run_model(request, &state, &discard_event, &|_, _, _| {
            panic!("a plan tool must not go through the ordinary approval gate")
        })
        .unwrap();
        server.join().unwrap();
        let card = answering.join().unwrap();

        assert_eq!(card.kind, crate::tool_prompt::PromptKind::PlanEnter);
        assert!(!card.allow_always_offered);
        assert!(card.mandatory);

        let entered = tool_output(&response, "enter_plan_mode");
        assert!(entered.success, "{}", entered.output);
        assert!(entered.output.starts_with("Entered plan mode."));

        assert_eq!(cell.get(), SecurityLevel::Plan);
        assert_eq!(
            store
                .conversation(&conversation_id)
                .unwrap()
                .unwrap()
                .settings
                .security_level,
            SecurityLevel::Plan
        );
    }

    #[test]
    fn agent_spawn_approval_precedes_reservation_and_observation() {
        for (level, hook_allow, answer, prompts, success) in [
            (SecurityLevel::RequestApproval, false, Ok(false), 1, false),
            (SecurityLevel::RequestApproval, false, Err("approval channel closed".to_owned()), 1, false),
            (SecurityLevel::RequestApproval, false, Ok(true), 1, true),
            (SecurityLevel::RequestApproval, true, Ok(false), 0, true),
            // Plan mode prompts for delegation on the same terms: the child is
            // read-only, but spawning it is still the run acting while the user
            // is deciding.
            (SecurityLevel::Plan, false, Ok(false), 1, false),
            (SecurityLevel::Plan, false, Ok(true), 1, true),
            (SecurityLevel::Plan, true, Ok(false), 0, true),
            (SecurityLevel::FullAccess, false, Ok(false), 0, true),
        ] {
            let (directory, state, mut parent, _) = named_agent_fixture(AgentDefinitionMemory::None);
            parent.security_level = level;
            let pool = AgentPool::new();
            let shadow = test_kernel_shadow();
            shadow.begin_turn();
            shadow.round_started();
            let call = ToolCall {
                id: "approval-spawn".into(), name: "agent_spawn".into(),
                input: serde_json::from_value(json!({"name":"approval-probe", "prompt":"review", "agent_type":"reviewer"})).unwrap(),
            };
            let digest = crate::kernel_shadow::call_params_digest(&call.input);
            shadow.tool_request(
                &call.id,
                matches!(level, SecurityLevel::RequestApproval | SecurityLevel::Plan),
                digest,
            );
            shadow.tool_dispatched(&call.id);
            let observed = std::sync::atomic::AtomicUsize::new(0);
            let approval = |_: &ToolExecutionRequest, _: &ToolDescriptor, _: ApprovalRequester<'_>| {
                assert!(pool.is_empty(), "approval must precede registration");
                assert!(state.reserved_subagent_names(&parent.conversation_id).is_empty(),
                    "denial must not leave a permanent name reservation");
                observed.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                if let Ok(granted) = &answer { shadow.record_prompt_outcome(*granted); }
                answer.clone()
            };
            let started = std::sync::atomic::AtomicBool::new(false);
            let sink = |event: ModelStreamEvent| -> Result<(), String> {
                if matches!(event, ModelStreamEvent::SubagentDelta { channel: SubagentChannel::Status, .. }) {
                    assert_eq!(observed.load(std::sync::atomic::Ordering::SeqCst), prompts, "approval must precede worker startup");
                    started.store(true, std::sync::atomic::Ordering::SeqCst);
                    // Cancel at the startup boundary so this dispatch test cannot
                    // contact any real provider, while still using the real worker path.
                    pool.find("approval-probe").unwrap().request_stop(agents::StopOrigin::Host);
                }
                Ok(())
            };
            let execution = run_agent_tool(agents::AgentToolKind::Spawn, &pool, &shadow,
                &parent, call, &state, &sink, &approval, hook_allow, 1).unwrap();
            shadow.tool_finished(&execution.call.id, false, hook_allow, execution.result.success, digest);
            assert_eq!(observed.load(std::sync::atomic::Ordering::SeqCst), prompts);
            assert_eq!(execution.result.success, success, "{}", execution.result.output);
            assert_eq!(started.load(std::sync::atomic::Ordering::SeqCst), success);
            if success {
                pool.wait_settled_for_tests(Duration::from_secs(5));
            } else {
                assert!(pool.is_empty());
                assert!(state.reserved_subagent_names(&parent.conversation_id).is_empty());
            }
            assert!(shadow.divergences().is_empty(), "{:?}", shadow.divergences());
            state.document_store.flush(Duration::from_secs(10)).unwrap();
            drop(directory);
        }
    }

    #[test]
    fn run_model_agent_spawn_denial_reaches_the_next_model_round_without_a_task() {
        let (directory, state, mut request, _) = named_agent_fixture(AgentDefinitionMemory::None);
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        request.provider.base_url = format!("http://{}/v1", listener.local_addr().unwrap());
        request.security_level = SecurityLevel::RequestApproval;
        let mut document = (*current_agent_document(&request, &state).unwrap()).clone();
        document.assets.api_providers = vec![request.provider.clone()];
        state.document_store.commit(&directory.path().join("document.v1.json"), document).unwrap();
        let server = serve_json_sequence(listener, vec![json!({
            "model":"model-test", "status":"completed",
            "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}, "output":[{
                "type":"function_call", "id":"fc_spawn", "call_id":"call_spawn",
                "name":"agent_spawn", "arguments":json!({"name":"denied-worker", "prompt":"review", "agent_type":"reviewer"}).to_string(),
                "status":"completed"
            }]
        }), responses_text_output("The delegation was denied.")]);
        let approvals = std::sync::atomic::AtomicUsize::new(0);
        let approval = |execution: &ToolExecutionRequest, _: &ToolDescriptor, _: ApprovalRequester<'_>| {
            assert_eq!(execution.tool_name, "agent_spawn");
            assert!(state.reserved_subagent_names(&request.conversation_id).is_empty());
            approvals.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            Ok(false)
        };
        let response = run_model(request.clone(), &state, &discard_event, &approval).unwrap();
        assert_eq!(approvals.load(std::sync::atomic::Ordering::SeqCst), 1, "{response:?}");
        let bodies = server.join().unwrap();
        assert_eq!(bodies.len(), 2);
        assert!(bodies[1].contains("The user denied this tool call."), "{}", bodies[1]);
        assert!(state.reserved_subagent_names(&request.conversation_id).is_empty());
        assert!(response.contexts.iter().any(|context| matches!(context,
            ContextItem::Tool { tool_name, result, .. } if tool_name == "agent_spawn" && !result.success)));
        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }

    #[test]
    fn running_child_round_checkpoint_survives_reopen_before_complete_turn() {
        let directory = tempfile::tempdir().unwrap();
        std::fs::write(directory.path().join("checkpoint.txt"), "ROUND_ONE_TOOL_BODY").unwrap();
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        listener.set_nonblocking(true).unwrap();
        let mut parent = loop_request_for(listener.local_addr().unwrap(), directory.path());
        parent.request_id = "child-round-checkpoint".into();
        let state = AppState::default();
        let pool = Arc::new(AgentPool::new());
        let spawn = ToolExecution {
            call: ToolCall { id: "spawn-checkpoint".into(), name: "agent_spawn".into(),
                input: serde_json::from_value(json!({"name":"checkpoint-worker", "prompt":"read checkpoint.txt"})).unwrap() },
            result: ToolResult { success: true, output: "ok".into(), images: Vec::new(), diff: None,
                executed_at: "2026-09-05T00:00:00Z".into(), duration_ms: 0 }, subagent: None,
        };
        let card = tool_context(&spawn, 1);
        let card_id = card.id().to_owned();
        parent.contexts.push(card);
        let store = persisted_conversation_for(&parent);
        let initial = vec![ContextItem::User { id: "child-task".into(), content: "read checkpoint.txt".into(),
            images: Vec::new(), created_at: "2026-09-05T00:00:00Z".into() }];
        let shared = pool.register("checkpoint-worker".into(), "checkpoint-worker".into(),
            "read checkpoint.txt".into(), agent_child_template(&parent), SubagentRunKind::General,
            &state, initial.clone(), Vec::new(), AgentLiveStatus::Running, spawn.call.id.clone(), None).unwrap();
        shared.record_call_context(&spawn.call.id, &card_id);
        let notices = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let notice_counter = Arc::clone(&notices);
        pool.set_settle_observer(Arc::new(move |_, _| { notice_counter.fetch_add(1, std::sync::atomic::Ordering::SeqCst); }));
        let (at_second_tx, at_second_rx) = std::sync::mpsc::channel();
        let (release_tx, release_rx) = std::sync::mpsc::channel();
        let server = thread::spawn(move || {
            let deadline = Instant::now() + Duration::from_secs(30);
            let accept = || loop {
                match listener.accept() {
                    Ok((stream, _)) => {
                        stream.set_nonblocking(false).unwrap();
                        stream.set_read_timeout(Some(Duration::from_secs(10))).unwrap();
                        break stream;
                    }
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock && Instant::now() < deadline => thread::yield_now(),
                    Err(error) => panic!("checkpoint fixture accept failed: {error}"),
                }
            };
            let mut first = accept();
            read_http_request_with_body(&mut first);
            write_sse_response(&mut first, &responses_sse(&json!({
                "model":"model-test", "status":"completed",
                "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2},
                "output":[
                    {"type":"message","id":"msg_first","status":"completed","role":"assistant",
                     "content":[{"type":"output_text","text":"ROUND_ONE_DURABLE"}]},
                    {"type":"function_call","id":"fc_read","call_id":"read_checkpoint","name":"read",
                     "arguments":json!({"path":"checkpoint.txt"}).to_string(),"status":"completed"}
                ]
            })));
            drop(first);
            let mut second = accept();
            let second_body = read_http_request_with_body(&mut second);
            at_second_tx.send(()).unwrap();
            release_rx.recv_timeout(Duration::from_secs(30)).unwrap();
            write_sse_response(&mut second, &responses_sse(&responses_text_output("FINAL_ROUND_DONE")));
            second_body
        });
        let worker_shared = Arc::clone(&shared);
        let worker_state = state.clone();
        // No task surface: persistence must not depend on a live parent renderer.
        let worker = thread::spawn(move || agent_worker_loop(&worker_shared, &worker_state, 1));
        at_second_rx.recv_timeout(Duration::from_secs(20)).unwrap();
        let status_at_checkpoint = shared.status();
        let transcript_at_checkpoint = shared.transcript();
        let notices_at_checkpoint = notices.load(std::sync::atomic::Ordering::SeqCst);
        let results_at_checkpoint = pool.take_undelivered_results();
        let reopened = crate::conversation_store::ConversationStore::open(
            &directory.path().join(crate::conversation_store::DATABASE_FILE_NAME)).unwrap();
        let recovery = reopened.conversation(&parent.conversation_id).unwrap().unwrap();
        release_tx.send(()).unwrap();
        worker.join().unwrap();
        let second_body = server.join().unwrap();
        assert!(second_body.contains("ROUND_ONE_TOOL_BODY"), "the first tool round really completed");
        assert_eq!(status_at_checkpoint, AgentLiveStatus::Running);
        assert_eq!(transcript_at_checkpoint, initial, "complete_turn has not appended any round yet");
        assert_eq!(notices_at_checkpoint, 0);
        assert!(results_at_checkpoint.is_empty());
        assert_eq!(recovery.contexts.len(), parent.contexts.len(), "child output must not pollute the parent timeline");
        let record = match recovery.contexts.iter().find(|item| item.id() == card_id).unwrap() {
            ContextItem::Tool { subagent: Some(record), attestation, .. } if !attestation.is_empty() => record,
            _ => panic!("the live child's settled round must already be durable and signed"),
        };
        assert_eq!(record.status, SubagentRunStatus::Interrupted);
        let contents = serde_json::to_string(&record.contexts).unwrap();
        assert!(contents.contains("ROUND_ONE_DURABLE"));
        assert!(contents.contains("ROUND_ONE_TOOL_BODY"));
        assert!(!contents.contains("FINAL_ROUND_DONE"));
        // Normal terminal backfill replaces the recovery copy, not appends to it.
        let mut history = parent.contexts.clone();
        let mut generated = GeneratedContexts::new(Some(ConversationSink {
            store: Arc::clone(&store), conversation_id: parent.conversation_id.clone(),
        }), None);
        let updates = checkpoint_terminal_agent_records(&pool, &parent.conversation_id,
            &parent.workspace_path, &state, &discard_event, 2, &mut history, &mut generated, &HashMap::new());
        generated.track_card_updates(updates);
        assert!(generated.checkpoint());
        let terminal = reopened.conversation(&parent.conversation_id).unwrap().unwrap();
        let ContextItem::Tool { subagent: Some(record), .. } = terminal.contexts.iter().find(|item| item.id() == card_id).unwrap()
            else { panic!("terminal record") };
        assert_eq!(record.status, SubagentRunStatus::Completed);
        assert_eq!(record.contexts.len(), record.contexts.iter().map(ContextItem::id).collect::<HashSet<_>>().len());
        assert!(serde_json::to_string(&record.contexts).unwrap().contains("FINAL_ROUND_DONE"));
    }

    #[test]
    fn running_child_checkpoint_retries_moves_owner_and_rejects_stale_incarnations() {
        let directory = tempfile::tempdir().unwrap();
        let parent = loop_request_for("127.0.0.1:9".parse().unwrap(), directory.path());
        let state = AppState::default();
        let pool = AgentPool::new();
        let template = agent_child_template(&parent);
        let shared = pool.register("draft-worker".into(), "draft-worker".into(), "draft task".into(),
            template.clone(), SubagentRunKind::General, &state, Vec::new(), Vec::new(),
            AgentLiveStatus::Running, "owner-1-call".into(), None).unwrap();
        let store = persisted_conversation_for(&parent);
        let spawn = ToolExecution {
            call: ToolCall { id: "owner-1-call".into(), name: "agent_spawn".into(),
                input: serde_json::from_value(json!({"name":"draft-worker", "prompt":"draft task"})).unwrap() },
            result: ToolResult { success: true, output: "ok".into(), images: Vec::new(), diff: None,
                executed_at: "2026-09-05T00:00:00Z".into(), duration_ms: 0 }, subagent: None,
        };
        let card = tool_context(&spawn, 1);
        let first_id = card.id().to_owned();
        shared.record_call_context("owner-1-call", &first_id);
        let new_sink = || SubagentTranscriptSink::for_child(&template, &state, Arc::clone(&shared), shared.identity());
        let mut generated = GeneratedContexts::new(None, None).with_transcript(new_sink());
        let prose = |id: &str, content: &str| ContextItem::Assistant { id: id.into(), content: content.into(),
            round: Some(1), model_turn_id: None, interrupted: false, sources: Vec::new(), created_at: "2026-09-05T00:00:00Z".into() };
        generated.push(prose("round-1", "FIRST_CHECKPOINT"));
        assert!(!generated.checkpoint(), "the parent's owner row is not on disk yet");
        store.upsert_contexts(&parent.conversation_id, &[card.clone()], crate::conversation_store::ContextStatus::Settled).unwrap();
        let read_card = |id: &str| store.conversation(&parent.conversation_id).unwrap().unwrap()
            .contexts.into_iter().find(|item| item.id() == id).unwrap();
        assert!(matches!(read_card(&first_id), ContextItem::Tool { subagent: None, .. }));
        let fault = rusqlite::Connection::open(directory.path().join(crate::conversation_store::DATABASE_FILE_NAME)).unwrap();
        let coordinates = || fault.query_row(
            "SELECT order_key, status, branch_id FROM context WHERE conversation_id = ?1 AND id = ?2",
            rusqlite::params![parent.conversation_id, first_id],
            |row| Ok((row.get::<_, f64>(0)?, row.get::<_, String>(1)?, row.get::<_, Option<String>>(2)?)),
        ).unwrap();
        let original_coordinates = coordinates();
        fault.execute_batch("CREATE TRIGGER fail_child_checkpoint BEFORE UPDATE ON context
            BEGIN SELECT RAISE(ABORT, 'child checkpoint failure'); END;").unwrap();
        assert!(!generated.checkpoint());
        assert!(generated.transcript.as_ref().unwrap().written.is_none());
        fault.execute_batch("DROP TRIGGER fail_child_checkpoint;").unwrap();
        assert!(generated.checkpoint(), "failed writes must be retried without new child output");
        assert_eq!(coordinates(), original_coordinates);
        assert!(matches!(read_card(&first_id), ContextItem::Tool { subagent: Some(record), .. }
            if record.status == SubagentRunStatus::Interrupted && record.contexts.len() == 1));
        assert_eq!(shared.status(), AgentLiveStatus::Running);
        assert!(shared.transcript().is_empty(), "a recovery copy must not change complete_turn's append base");
        assert!(pool.take_undelivered_results().is_empty());
        // The same transcript must move to a later owner even if its bytes did
        // not change. Both the new holder and the cleared old holder are signed.
        let mut next_card = card;
        if let ContextItem::Tool { id, tool_name, .. } = &mut next_card {
            *id = "owner-2".into();
            *tool_name = "send_message".into();
        }
        store.upsert_contexts(&parent.conversation_id, &[next_card], crate::conversation_store::ContextStatus::Settled).unwrap();
        shared.record_message_call("owner-2-call");
        shared.record_call_context("owner-2-call", "owner-2");
        fault.execute_batch("CREATE TRIGGER fail_old_holder BEFORE UPDATE ON context
            WHEN OLD.id != 'owner-2' BEGIN SELECT RAISE(ABORT, 'old holder failure'); END;").unwrap();
        assert!(!generated.checkpoint());
        assert!(matches!(read_card(&first_id), ContextItem::Tool { subagent: Some(_), .. }));
        assert!(matches!(read_card("owner-2"), ContextItem::Tool { subagent: None, .. }),
            "failure clearing the old holder must roll back the new holder too");
        fault.execute_batch("DROP TRIGGER fail_old_holder;").unwrap();
        assert!(generated.checkpoint());
        assert!(matches!(read_card(&first_id), ContextItem::Tool { subagent: None, attestation, .. } if !attestation.is_empty()));
        assert!(matches!(read_card("owner-2"), ContextItem::Tool { subagent: Some(_), .. }));
        let old = shared.identity();
        shared.complete_turn(old, generated.items.clone(), "done".into(), AgentLiveStatus::Idle,
            &ModelUsage::default(), 1, None);
        shared.take_undelivered_results();
        assert!(shared.begin_turn("next-incarnation"));
        shared.record_call_context("next-incarnation", "owner-2");
        let mut successor = GeneratedContexts::new(None, None).with_transcript(new_sink());
        successor.push(prose("round-2", "SUCCESSOR_CHECKPOINT"));
        assert!(successor.checkpoint());
        let before = read_card("owner-2");
        generated.push(prose("late-old", "STALE_CHECKPOINT"));
        assert!(!generated.checkpoint(), "old incarnation must be refused even while its successor is Running");
        assert_eq!(read_card("owner-2"), before);
        assert!(pool.take_undelivered_results().is_empty());
    }

