    /// The ChatGPT Codex backend answers `400 Unsupported parameter:
    /// max_output_tokens`, so the step must not carry the budget even when the
    /// model profile sets one. The sidecar strips it again; this pins the host.
    #[test]
    fn codex_requests_carry_no_output_budget() {
        let mut request = run_request(ProviderFamily::OpenaiCodex);
        request.model.max_output_tokens = Some(4096);

        let step = step_json(&request);

        assert!(step.get("maxOutputTokens").is_none(), "{step}");
        assert_eq!(step["family"], "openai-codex");
    }

    /// An empty Codex address resolves to the fixed ChatGPT backend on the host,
    /// so the sidecar never has to know the default; a loopback override still
    /// wins so a test double can stand in for the backend.
    #[test]
    fn an_empty_codex_address_resolves_to_the_chatgpt_backend() {
        let mut provider = provider(ProviderFamily::OpenaiCodex);
        provider.base_url = String::new();
        assert_eq!(
            provider_base_url(&provider).unwrap().map(|url| url.to_string()),
            Some("https://chatgpt.com/backend-api/codex".to_owned())
        );
        // The Codex path is not an endpoint suffix and must survive normalization.
        assert_eq!(
            provider_base_url(&provider).unwrap().unwrap().path(),
            "/backend-api/codex"
        );

        provider.base_url = "http://127.0.0.1:9/backend-api/codex".into();
        assert_eq!(
            provider_base_url(&provider).unwrap().map(|url| url.to_string()),
            Some("http://127.0.0.1:9/backend-api/codex".to_owned())
        );

        // The ChatGPT session must never travel to a third-party host: a remote
        // override is refused even though it would be a valid address elsewhere.
        provider.base_url = "https://relay.example.com/backend-api/codex".into();
        let error = provider_base_url(&provider).unwrap_err();
        assert!(error.contains("本机"), "{error}");
    }

    /// Without a Codex session the run fails before any request, with an error
    /// that names the remedy, and never falls back to the credential slot's raw
    /// contents (which hold the OAuth master key, not a bearer token).
    #[test]
    fn a_signed_out_codex_provider_is_rejected_before_dispatch() {
        let mut provider = provider(ProviderFamily::OpenaiCodex);
        provider.id = "provider_codex_signed_out_test".into();
        provider.base_url = String::new();
        // Even a stray plain key in the slot must not be treated as a session.
        save_api_key(&provider.id, "sk-not-a-session").unwrap();

        let base_url = provider_base_url(&provider).unwrap();
        let error = initial_provider_key(&provider, &base_url).unwrap_err();
        assert!(error.contains("登录"), "{error}");
        assert!(step_credential(&provider, &None).is_err());
        delete_api_key(&provider.id).unwrap();
    }

    /// The Claude Agent family authenticates with the user's own CLI login, so
    /// the row carries neither an address nor a credential. Both fields may
    /// still hold values an older version wrote — that is what an upgraded
    /// profile looks like — and neither may be used or rejected.
    #[test]
    fn a_claude_agent_row_has_neither_an_address_nor_a_credential() {
        let mut provider = provider(ProviderFamily::ClaudeAgent);
        provider.id = "provider_claude_agent_legacy_test".into();
        provider.base_url = "https://api.anthropic.com".into();
        // A key left in the slot must not be read back into a request.
        save_api_key(&provider.id, "sk-left-over").unwrap();

        validate_provider(&provider).unwrap();
        let base_url = provider_base_url(&provider).unwrap();
        assert_eq!(base_url, None);
        assert_eq!(initial_provider_key(&provider, &base_url).unwrap(), None);

        // A string the URL parser cannot even read must not brick the profile.
        provider.base_url = "not a url".into();
        validate_provider(&provider).unwrap();
        assert_eq!(provider_base_url(&provider).unwrap(), None);

        provider.base_url = String::new();
        assert_eq!(provider_base_url(&provider).unwrap(), None);
        assert_eq!(initial_provider_key(&provider, &None).unwrap(), None);

        delete_api_key(&provider.id).unwrap();
    }

    /// The two families whose credential slot is not the user's to manage. Each
    /// refusal names why, because the button that reached here looks ordinary.
    #[test]
    fn the_login_owning_families_refuse_every_manual_key_command() {
        for command in [
            ApiKeyCommand::Save,
            ApiKeyCommand::Reveal,
            ApiKeyCommand::Delete,
        ] {
            let error =
                refuse_api_key_command(ProviderFamily::ClaudeAgent, command).unwrap_err();
            assert!(error.contains("Claude Code"), "{error}");
            assert!(error.contains("API Key"), "{error}");

            let error = refuse_api_key_command(ProviderFamily::OpenaiCodex, command).unwrap_err();
            assert!(error.contains("OpenAI Codex"), "{error}");

            // Every other family manages its own key as before.
            for family in [
                ProviderFamily::Anthropic,
                ProviderFamily::OpenaiChat,
                ProviderFamily::OpenaiResponses,
                ProviderFamily::OpenaiCompatible,
                ProviderFamily::Google,
                ProviderFamily::Vertex,
                ProviderFamily::Bedrock,
                ProviderFamily::Azure,
                ProviderFamily::Xai,
            ] {
                refuse_api_key_command(family, command).unwrap();
            }
        }
    }

