        #[test]
    fn automatic_tool_round_is_serialized_but_never_enters_api_history() {
        let execution = ToolExecution {
            call: ToolCall {
                id: "call-round".into(),
                name: "read".into(),
                input: serde_json::from_value(json!({"path":"README.md"})).unwrap(),
            },
            result: ToolResult {
                success: true,
                output: "contents".into(),
                images: Vec::new(),
                diff: None,
                executed_at: "2026-01-01T00:00:00Z".into(),
                duration_ms: 1,
            },
            subagent: None,
        };
        let with_round = tool_context(&execution, 3);
        assert_eq!(serde_json::to_value(&with_round).unwrap()["round"], 3);
        assert!(matches!(
            &with_round,
            ContextItem::Tool { round: Some(3), .. }
        ));

        let mut without_round = with_round.clone();
        let ContextItem::Tool { round, .. } = &mut without_round else {
            unreachable!();
        };
        *round = None;

        for format in [
            ProviderFamily::OpenaiResponses,
            ProviderFamily::OpenaiChat,
            ProviderFamily::Anthropic,
        ] {
            let mut request_with_round = run_request(format);
            request_with_round.contexts.push(with_round.clone());
            let mut request_without_round = request_with_round.clone();
            *request_without_round.contexts.last_mut().unwrap() = without_round.clone();

            assert_eq!(
                step_json(&request_with_round),
                step_json(&request_without_round),
                "tool round metadata must not alter {format:?} history"
            );
        }
    }


    #[test]
    fn dangerous_and_orchestration_calls_pass_while_unknown_and_disabled_are_rejected() {
        let mut request = run_request(ProviderFamily::OpenaiResponses);
        request.tools = catalog::tool_catalog();
        request.enabled_tools = request
            .tools
            .iter()
            .map(|tool| tool.name.clone())
            .filter(|name| name != "todo")
            .collect();
        let dangerous = ToolCall {
            id: "dangerous".into(),
            name: "powershell".into(),
            input: serde_json::from_value(json!({"command":"echo nope"})).unwrap(),
        };
        let unknown = ToolCall {
            id: "unknown".into(),
            name: "not_a_tool".into(),
            input: Map::new(),
        };
        let orchestration = ToolCall {
            id: "orchestration".into(),
            name: "agent_spawn".into(),
            input: serde_json::from_value(json!({"prompt":"do work"})).unwrap(),
        };
        let disabled = ToolCall {
            id: "disabled".into(),
            name: "todo".into(),
            input: serde_json::from_value(json!({"action":"list"})).unwrap(),
        };

        assert_eq!(automatic_tool_rejection_reason(&request, &dangerous), None);
        assert_eq!(
            automatic_tool_rejection_reason(&request, &orchestration),
            None
        );
        assert_eq!(
            automatic_tool_rejection_reason(&request, &unknown),
            Some("The model requested an unknown tool")
        );
        assert_eq!(
            automatic_tool_rejection_reason(&request, &disabled),
            Some("The model requested a tool that is not enabled")
        );
    }

