    /// Stopping a background task must interrupt a shell command already running on
    /// its synchronous leg. The test stops only the task after its command record
    /// appears, then requires a terminal stopped record well before the command timeout.
    #[test]
    fn stopping_a_task_kills_the_shell_that_task_is_blocked_on() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = thread::spawn(move || {
            listener.set_nonblocking(true).unwrap();
            let deadline = Instant::now() + Duration::from_secs(25);
            let mut served = 0usize;
            while served == 0 && Instant::now() < deadline {
                match listener.accept() {
                    Ok((mut stream, _)) => {
                        stream.set_nonblocking(false).unwrap();
                        let _ = read_http_request_with_body(&mut stream);
                        let response = json!({
                            "model": "model-test",
                            "status": "completed",
                            "output": [{
                                "type":"function_call","status":"completed",
                                "call_id":"call-sleep","name":"bash",
                                "arguments":json!({"command":"sleep 20"}).to_string()
                            }],
                            "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}
                        });
                        write_json_response(&mut stream, "200 OK", &response);
                        served += 1;
                        drop(stream);
                    }
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        thread::sleep(Duration::from_millis(10));
                    }
                    Err(_) => break,
                }
            }
            served
        });

        let workspace = tempfile::tempdir().unwrap();
        let parent = loop_request_for(address, workspace.path());
        let conversation_id = parent.conversation_id.clone();
        let state = AppState::default();
        let pool = AgentPool::new();
        let (parent_run, _steer) = state
            .begin_model_run("run-parent", &conversation_id)
            .unwrap();
        // Task approvals are delivered through the conversation surface.
        state.register_task_surface(
            &conversation_id,
            Arc::new(crate::state::TaskSurface {
                sink: Arc::new(|_: ModelStreamEvent| Ok(())),
                approve: Arc::new(
                    |_: &ToolExecutionRequest,
                     _: &ToolDescriptor,
                     _: ApprovalRequester<'_>,
                     _: Option<&AtomicBool>| Ok(true),
                ),
            }),
        );
        let shared = pool
            .register(
                "a1".into(),
                "a1".into(),
                "跑一条很长的命令".into(),
                agent_child_template(&parent),
                SubagentRunKind::General,
                &state,
                vec![ContextItem::User {
                    id: "subagent-task-1".into(),
                    content: "跑一条很长的命令".into(),
                    images: Vec::new(),
                    created_at: "2026-01-01T00:00:00Z".into(),
                }],
                Vec::new(),
                AgentLiveStatus::Running,
                "call-a1".into(),
                None,
            )
            .unwrap();
        spawn_agent_worker(Arc::clone(&shared), &state, 0);

        let spawn_deadline = Instant::now() + Duration::from_secs(20);
        loop {
            if !state.shell_tasks.task_snapshots(&conversation_id).is_empty() {
                break;
            }
            assert!(
                Instant::now() < spawn_deadline,
                "子代理始终没有把命令跑起来：status={:?} envelopes={:?}",
                shared.status(),
                shared
                    .take_undelivered_results()
                    .into_iter()
                    .map(|envelope| envelope.content)
                    .collect::<Vec<_>>()
            );
            thread::sleep(Duration::from_millis(20));
        }
        let stopped_at = Instant::now();
        shared.request_stop(crate::agents::StopOrigin::User);

        let outcome_deadline = Instant::now() + Duration::from_secs(15);
        let outcome = loop {
            let rows = state.shell_tasks.task_snapshots(&conversation_id);
            assert_eq!(rows.len(), 1, "只应该有那一条命令");
            if let Some(outcome) = rows[0].outcome {
                break outcome;
            }
            assert!(
                Instant::now() < outcome_deadline,
                "任务已停止，命令却还在跑：{:?}",
                stopped_at.elapsed()
            );
            thread::sleep(Duration::from_millis(20));
        };
        assert!(
            stopped_at.elapsed() < Duration::from_secs(15),
            "停止必须在一个轮询周期内到达命令，而不是等它跑满 20 秒：{:?}",
            stopped_at.elapsed()
        );
        assert_eq!(
            outcome,
            ShellTaskOutcome::Stopped,
            "被用户停止的命令不能记成失败"
        );
        pool.wait_settled_for_tests(Duration::from_secs(30));
        assert_eq!(shared.status(), AgentLiveStatus::Interrupted);
        // The stop is not a discard: the settled envelope carries what the task
        // produced plus the profile's user-close sentence, and it is deliverable.
        assert!(
            pool.has_undrained_foldable_results(),
            "被用户关闭的任务同样欠一轮交付"
        );
        let claimed = pool.take_undelivered_results();
        assert_eq!(claimed.len(), 1);
        assert!(
            claimed[0].content.contains("The user manually closed this task"),
            "结果正文必须说清是用户手动关闭的：{}",
            claimed[0].content
        );
        assert!(
            !parent_run.load(Ordering::SeqCst),
            "这条测试不得借道运行级取消"
        );
        assert_eq!(server.join().unwrap(), 1, "只应该有那一次子回合请求");
    }

    fn serve_child_tool_call(
        listener: TcpListener,
        first: Value,
        budget: Duration,
    ) -> thread::JoinHandle<usize> {
        thread::spawn(move || {
            listener.set_nonblocking(true).unwrap();
            let deadline = Instant::now() + budget;
            let mut served = 0usize;
            while served == 0 && Instant::now() < deadline {
                match listener.accept() {
                    Ok((mut stream, _)) => {
                        stream.set_nonblocking(false).unwrap();
                        let _ = read_http_request_with_body(&mut stream);
                        write_json_response(&mut stream, "200 OK", &first);
                        served += 1;
                        drop(stream);
                    }
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        thread::sleep(Duration::from_millis(10));
                    }
                    Err(_) => break,
                }
            }
            served
        })
    }

    fn blocking_hook(marker: &str) -> crate::model::HookDefinition {
        #[cfg(windows)]
        let command = format!(
            "$input | Out-Null; New-Item -ItemType File -Path {marker} | Out-Null; Start-Sleep -Seconds 20"
        );
        #[cfg(not(windows))]
        let command = format!("cat >/dev/null; touch {marker}; sleep 20");
        crate::model::HookDefinition {
            id: "blocking-pre-tool-use".into(),
            name: "阻塞的 PreToolUse 钩子".into(),
            event: HookEvent::PreToolUse,
            matcher: None,
            command,
            command_windows: None,
            status_message: None,
            enabled: true,
            timeout_ms: 120_000,
        }
    }

    /// Wait for a barrier condition until its deadline and return whether it was met.
    fn wait_for(condition: impl Fn() -> bool) -> bool {
        let deadline = Instant::now() + Duration::from_secs(20);
        while Instant::now() < deadline {
            if condition() {
                return true;
            }
            thread::sleep(Duration::from_millis(20));
        }
        false
    }

    /// Stopping a background task must also interrupt its running hook command.
    /// The task cancellation flag is threaded through `HookRunServices` to the
    /// command runner's polling loop; the hook marker is the test barrier.
    #[test]
