    #[test]
    fn task_wait_handles_missing_agents_and_non_agent_tasks_without_a_network() {
        let request = run_request(ProviderFamily::OpenaiResponses);
        let state = AppState::default();
        let pool = AgentPool::new();

        // Waiting with no tasks at all returns an immediate hint.
        let wait = run_task_wait(
            &pool,
            &test_kernel_shadow(),
            &request,
            ToolCall {
                id: "call-wait".into(),
                name: "task_wait".into(),
                input: Map::new(),
            },
            &state,
            &discard_event,
            1,
        )
        .unwrap();
        assert!(wait.result.success);
        assert!(wait
            .result
            .output
            .contains(PromptKey::TaskWaitIdle.builtin_en()));

        // Waiting on an unknown name fails with guidance.
        let unknown = run_task_wait(
            &pool,
            &test_kernel_shadow(),
            &request,
            ToolCall {
                id: "call-wait-unknown".into(),
                name: "task_wait".into(),
                input: serde_json::from_value(json!({"tasks":["ghost"]})).unwrap(),
            },
            &state,
            &discard_event,
            1,
        )
        .unwrap();
        assert!(!unknown.result.success);
        assert!(
            unknown.result.output.contains("There is no subagent named ghost"),
            "{}",
            unknown.result.output
        );

        // A terminal or browser address that names nothing fails the same way rather than
        // silently watching an empty set until the timeout.
        for (address, expected) in [
            ("terminal:ghost", "There is no terminal terminal:ghost"),
            ("browser:ghost", "There is no browser tab browser:ghost"),
        ] {
            let missing = run_task_wait(
                &pool,
                &test_kernel_shadow(),
                &request,
                ToolCall {
                    id: format!("call-wait-{address}"),
                    name: "task_wait".into(),
                    input: serde_json::from_value(json!({"tasks":[address]})).unwrap(),
                },
                &state,
                &discard_event,
                1,
            )
            .unwrap();
            assert!(!missing.result.success, "{}", missing.result.output);
            assert!(
                missing.result.output.contains(expected),
                "{}",
                missing.result.output
            );
        }
    }

    /// Mixed waits must also wait for non-pooled tasks, even if the named pooled
    /// task has already settled.
    #[test]
    fn a_mixed_wait_also_waits_for_its_non_pool_tasks() {
        let request = run_request(ProviderFamily::OpenaiResponses);
        let state = AppState::default();
        let pool = AgentPool::new();
        // A terminal agent with no requested result cannot delay this wait.
        pool.register(
            "a1".into(),
            "a1".into(),
            "早就跑完了".into(),
            agent_child_template(&request),
            SubagentRunKind::General,
            &state,
            Vec::new(),
            Vec::new(),
            AgentLiveStatus::Idle,
            "call-a1".into(),
            None,
        )
        .unwrap();
        // A synchronous task has no pool entry and must be observed by snapshot polling.
        let _guard = state
            .shell_tasks
            .register(&request.conversation_id, "bash", "sleep 600", false);
        let shell_ref = format!("shell:{}", _guard.shell_task_id());

        let started = Instant::now();
        let wait = run_task_wait(
            &pool,
            &test_kernel_shadow(),
            &request,
            ToolCall {
                id: "call-mixed".into(),
                name: "task_wait".into(),
                input: serde_json::from_value(
                    json!({"tasks":["a1",shell_ref],"timeout_seconds":5}),
                )
                .unwrap(),
            },
            &state,
            &discard_event,
            1,
        )
        .unwrap();
        assert!(wait.result.success, "{}", wait.result.output);
        assert!(
            started.elapsed() >= Duration::from_secs(5),
            "命令还在跑，混合等待必须真的等到期限，而不是在 a1 那边一了结就返回"
        );
        assert!(
            wait.result.output.contains(&shell_ref),
            "超时文案要点名还在跑的那条命令：{}",
            wait.result.output
        );
    }

    /// `task_list` groups every kind of task. With an empty conversation the
    /// groups are all empty, and the empty-state text must say so once rather
    /// than printing three bare headers.
    #[test]
    fn task_list_includes_recovered_shell_history_without_creating_pool_tasks() {
        let directory = tempfile::tempdir().unwrap();
        let request = run_request(ProviderFamily::OpenaiResponses);
        let first = AppState::default();
        first.shell_tasks.install_store(directory.path()).unwrap();
        let mut guard = first.shell_tasks.try_register(&request.conversation_id, "bash", "historical build", true).unwrap();
        let address = format!("shell:{}", guard.shell_task_id());
        guard.finish(ShellTaskOutcome::Failed, Some(2));
        drop(guard);
        drop(first);
        let restored = AppState::default();
        restored.shell_tasks.install_store(directory.path()).unwrap();
        let pool = AgentPool::new();
        let listed = run_task_list(&pool, &request, ToolCall {
            id: "restored-list".into(), name: "task_list".into(), input: Map::new(),
        }, &restored);
        assert!(listed.result.success);
        assert!(listed.result.output.contains(&address), "{}", listed.result.output);
        assert!(listed.result.output.contains(PromptKey::TaskGroupShellCommands.builtin_en()));
        assert!(listed.result.output.contains("historical build"));
        assert!(pool.all().is_empty());
    }

    #[test]
    fn task_list_reports_an_empty_conversation_once() {
        let request = run_request(ProviderFamily::OpenaiResponses);
        let state = AppState::default();
        let pool = AgentPool::new();

        let listed = run_task_list(
            &pool,
            &request,
            ToolCall {
                id: "call-list".into(),
                name: "task_list".into(),
                input: Map::new(),
            },
            &state,
        );
        assert!(listed.result.success);
        assert!(
            listed
                .result
                .output
                .contains(PromptKey::TaskListEmpty.builtin_en()),
            "{}",
            listed.result.output
        );
        // The empty state is one sentence. Group headers are emitted as their own
        // lines, so any newline here would mean a bare header slipped through.
        assert!(!listed.result.output.contains('\n'), "{}", listed.result.output);
    }

    #[test]
    fn finalize_attaches_records_to_the_latest_agent_tool_context() {
        let pool = AgentPool::new();
        let template = run_request(ProviderFamily::OpenaiResponses);
        let shared = pool
            .register(
                "a1".into(),
                "a1".into(),
                "任务".into(),
                template,
                SubagentRunKind::General,
                &AppState::default(),
                vec![ContextItem::User {
                    id: "task".into(),
                    content: "任务".into(),
                    images: Vec::new(),
                    created_at: "2026-07-14T00:00:00Z".into(),
                }],
                Vec::new(),
                AgentLiveStatus::Running,
                "call-spawn".into(),
                None,
            )
            .unwrap();
        shared.complete_turn(
            shared.identity(),
            vec![ContextItem::Assistant {
                id: "answer".into(),
                content: "结论".into(),
                round: None,
                model_turn_id: None,
                interrupted: false,
                sources: Vec::new(),
                created_at: "2026-07-14T00:00:01Z".into(),
            }],
            "结论".into(),
            AgentLiveStatus::Idle,
            &ModelUsage {
                input_tokens: Some(3),
                cached_input_tokens: Some(2),
                output_tokens: Some(4),
                total_tokens: Some(7),
                reasoning_tokens: None,
            },
            0,
            None,
        );

        let spawn_execution = ToolExecution {
            call: ToolCall {
                id: "call-spawn".into(),
                name: "agent_spawn".into(),
                input: serde_json::from_value(json!({"prompt":"任务","name":"a1"})).unwrap(),
            },
            result: ToolResult {
                success: true,
                output: orchestration::agent_spawn_output("a1"),
                images: Vec::new(),
                diff: None,
                executed_at: "2026-07-14T00:00:00Z".into(),
                duration_ms: 0,
            },
            subagent: None,
        };
        let mut generated = vec![tool_context(&spawn_execution, 1)];
        let context_id = generated[0].id().to_owned();
        let agent_context_ids = HashMap::from([("call-spawn".into(), context_id)]);
        let mut usage = ModelUsage::default();
        finalize_agent_pool(&pool, &mut generated, &mut usage, &agent_context_ids);

        assert_eq!(usage.total_tokens, Some(7));
        let record = generated
            .iter()
            .find_map(|context| match context {
                ContextItem::Tool {
                    tool_name,
                    subagent,
                    ..
                } if tool_name == "agent_spawn" => subagent.as_ref(),
                _ => None,
            })
            .expect("record backfilled onto the spawn context");
        assert_eq!(record.name.as_deref(), Some("a1"));
        assert_eq!(record.status, SubagentRunStatus::Completed);
        assert_eq!(record.contexts.len(), 2);

        let request = run_request(ProviderFamily::OpenaiResponses);
        let state = AppState::default();
        record_generated_subagent_receipts(&request, &mut generated, &state);
        let ContextItem::Tool {
            tool_name,
            input,
            result,
            subagent: Some(record),
            ..
        } = &generated[0]
        else {
            panic!("finalized agent tool context must carry its audit record");
        };
        assert!(state.has_subagent_receipt(
            &request.workspace_path,
            &request.conversation_id,
            tool_name,
            input,
            result,
            record,
        ));
    }

    #[test]
    fn round_boundary_checkpoint_backfills_reattests_and_emits_the_settled_card() {
        let pool = AgentPool::new();
        let template = run_request(ProviderFamily::OpenaiResponses);
        let shared = pool
            .register(
                "a1".into(),
                "a1".into(),
                "任务".into(),
                template,
                SubagentRunKind::General,
                &AppState::default(),
                vec![ContextItem::User {
                    id: "task".into(),
                    content: "任务".into(),
                    images: Vec::new(),
                    created_at: "2026-07-14T00:00:00Z".into(),
                }],
                Vec::new(),
                AgentLiveStatus::Running,
                "call-spawn".into(),
                None,
            )
            .unwrap();
        shared.complete_turn(
            shared.identity(),
            vec![ContextItem::Assistant {
                id: "answer".into(),
                content: "结论".into(),
                round: None,
                model_turn_id: None,
                interrupted: false,
                sources: Vec::new(),
                created_at: "2026-07-14T00:00:01Z".into(),
            }],
            "结论".into(),
            AgentLiveStatus::Idle,
            &ModelUsage::default(),
            0,
            None,
        );

        let spawn_execution = ToolExecution {
            call: ToolCall {
                id: "call-spawn".into(),
                name: "agent_spawn".into(),
                input: serde_json::from_value(json!({"prompt":"任务","name":"a1"})).unwrap(),
            },
            result: ToolResult {
                success: true,
                output: orchestration::agent_spawn_output("a1"),
                images: Vec::new(),
                diff: None,
                executed_at: "2026-07-14T00:00:00Z".into(),
                duration_ms: 0,
            },
            subagent: None,
        };
        let mut generated = vec![tool_context(&spawn_execution, 1)];
        let context_id = generated[0].id().to_owned();
        let agent_context_ids = HashMap::from([("call-spawn".to_owned(), context_id)]);
        let request = run_request(ProviderFamily::OpenaiResponses);
        let state = AppState::default();
        let events = std::sync::Mutex::new(Vec::<ModelStreamEvent>::new());
        let sink = |event: ModelStreamEvent| -> Result<(), String> {
            events.lock().unwrap().push(event);
            Ok(())
        };
        let mut request_contexts = Vec::<ContextItem>::new();
        checkpoint_terminal_agent_records(
            &pool,
            &request.conversation_id,
            &request.workspace_path,
            &state,
            &sink,
            2,
            &mut request_contexts,
            &mut generated,
            &agent_context_ids,
        );

        let ContextItem::Tool {
            id,
            tool_name,
            requested_input,
            input,
            result,
            subagent: Some(record),
            attestation,
            ..
        } = &generated[0]
        else {
            panic!("checkpoint must backfill the terminal record onto the spawn card");
        };
        assert_eq!(record.status, SubagentRunStatus::Completed);
        assert!(state.verify_tool_context(
            &crate::tool_attestation::AttestationSubject {
                conversation_id: &request.conversation_id,
                context_id: id,
                tool_name,
                input,
                requested_input: requested_input.as_ref(),
                result,
                subagent: Some(record),
            },
            attestation,
        ));
        {
            let captured = events.lock().unwrap();
            assert_eq!(captured.len(), 1, "one settled-card event per new record");
            let ModelStreamEvent::ToolContextSettled { round, context } = &captured[0] else {
                panic!("the checkpoint event must carry the settled card");
            };
            assert_eq!(*round, 2);
            assert!(matches!(
                &**context,
                ContextItem::Tool { subagent: Some(_), .. }
            ));
        }

        checkpoint_terminal_agent_records(
            &pool,
            &request.conversation_id,
            &request.workspace_path,
            &state,
            &sink,
            3,
            &mut request_contexts,
            &mut generated,
            &agent_context_ids,
        );
        assert_eq!(events.lock().unwrap().len(), 1);
    }

    #[test]
    fn round_boundary_checkpoint_reaches_a_cross_turn_card_via_the_agent_coordinates() {
        let pool = AgentPool::new();
        let template = run_request(ProviderFamily::OpenaiResponses);
        let shared = pool
            .register(
                "a1".into(),
                "a1".into(),
                "任务".into(),
                template,
                SubagentRunKind::General,
                &AppState::default(),
                Vec::new(),
                Vec::new(),
                AgentLiveStatus::Running,
                "call-spawn".into(),
                None,
            )
            .unwrap();

        let spawn_execution = ToolExecution {
            call: ToolCall {
                id: "call-spawn".into(),
                name: "agent_spawn".into(),
                input: serde_json::from_value(json!({"prompt":"任务","name":"a1"})).unwrap(),
            },
            result: ToolResult {
                success: true,
                output: orchestration::agent_spawn_output("a1"),
                images: Vec::new(),
                diff: None,
                executed_at: "2026-07-14T00:00:00Z".into(),
                duration_ms: 0,
            },
            subagent: None,
        };
        let mut history = vec![tool_context(&spawn_execution, 1)];
        let context_id = history[0].id().to_owned();
        shared.record_call_context("call-spawn", &context_id);
        shared.complete_turn(
            shared.identity(),
            vec![ContextItem::Assistant {
                id: "answer".into(),
                content: "结论".into(),
                round: None,
                model_turn_id: None,
                interrupted: false,
                sources: Vec::new(),
                created_at: "2026-07-14T00:00:01Z".into(),
            }],
            "结论".into(),
            AgentLiveStatus::Idle,
            &ModelUsage::default(),
            0,
            None,
        );

        let request = run_request(ProviderFamily::OpenaiResponses);
        let state = AppState::default();
        let directory = tempfile::tempdir().unwrap();
        let db_path = directory.path().join(crate::conversation_store::DATABASE_FILE_NAME);
        let store = Arc::new(crate::conversation_store::ConversationStore::open(&db_path).unwrap());
        let mut document = catalog::default_document(directory.path());
        let conversation = &mut document.workspaces[0].conversations[0];
        conversation.id = request.conversation_id.clone();
        conversation.contexts = history.clone();
        store.put_conversation("workspace", conversation).unwrap();
        let mut generated = GeneratedContexts::new(Some(ConversationSink {
            store: Arc::clone(&store),
            conversation_id: request.conversation_id.clone(),
        }), Some(context_id.clone()));
        let card_updates = checkpoint_terminal_agent_records(
            &pool,
            &request.conversation_id,
            &request.workspace_path,
            &state,
            &discard_event,
            1,
            &mut history,
            &mut generated,
            &HashMap::new(),
        );
        generated.track_card_updates(card_updates);
        let fault = rusqlite::Connection::open(&db_path).unwrap();
        fault.execute_batch(
            "CREATE TRIGGER block_history_update BEFORE UPDATE ON context
             BEGIN SELECT RAISE(ABORT, 'history checkpoint fault'); END;
             CREATE TRIGGER block_history_insert BEFORE INSERT ON context
             BEGIN SELECT RAISE(ABORT, 'history checkpoint fault'); END;"
        ).unwrap();
        assert!(!generated.checkpoint());
        assert_eq!(generated.historical_updates.len(), 1);
        // Memory is already equal, so a later backfill has no new updates. The
        // failed write must remain independently pending across that boundary.
        let repeated = checkpoint_terminal_agent_records(
            &pool, &request.conversation_id, &request.workspace_path, &state,
            &discard_event, 2, &mut history, &mut generated, &HashMap::new(),
        );
        assert!(repeated.is_empty());
        generated.track_card_updates(repeated);
        fault.execute_batch("DROP TRIGGER block_history_update; DROP TRIGGER block_history_insert;").unwrap();
        assert!(generated.checkpoint());
        assert!(generated.historical_updates.is_empty());
        let reopened = crate::conversation_store::ConversationStore::open(&db_path).unwrap();
        let durable = reopened.conversation(&request.conversation_id).unwrap().unwrap();
        assert_eq!(durable.contexts.len(), 1);
        assert_eq!(durable.contexts[0].id(), context_id);
        assert!(matches!(&durable.contexts[0], ContextItem::Tool { subagent: Some(record), .. }
            if record.status == SubagentRunStatus::Completed && record.contexts.len() == 1),
            "the historical card must reach SQLite, not only the renderer");

        assert!(
            matches!(
                &history[0],
                ContextItem::Tool { subagent: Some(record), .. }
                    if record.status == SubagentRunStatus::Completed
            ),
            "a child that outlived its spawning request must still reach its history card"
        );
    }

    /// After continuation, records move to the latest call card rather than remaining
    /// duplicated on earlier cards, preserving single ownership and avoiding O(n²) growth.
    #[test]
    fn round_boundary_checkpoint_moves_the_record_off_a_superseded_card() {
        let pool = AgentPool::new();
        let template = run_request(ProviderFamily::OpenaiResponses);
        let shared = pool
            .register(
                "a1".into(),
                "a1".into(),
                "任务".into(),
                template,
                SubagentRunKind::General,
                &AppState::default(),
                Vec::new(),
                Vec::new(),
                AgentLiveStatus::Running,
                "call-spawn".into(),
                None,
            )
            .unwrap();
        let tool_execution_for = |call_id: &str, name: &str| ToolExecution {
            call: ToolCall {
                id: call_id.into(),
                name: name.into(),
                input: serde_json::from_value(json!({"prompt":"任务","name":"a1"})).unwrap(),
            },
            result: ToolResult {
                success: true,
                output: orchestration::agent_spawn_output("a1"),
                images: Vec::new(),
                diff: None,
                executed_at: "2026-07-14T00:00:00Z".into(),
                duration_ms: 0,
            },
            subagent: None,
        };
        let settle = |text: &str, id: &str| {
            shared.complete_turn(
                shared.identity(),
                vec![ContextItem::Assistant {
                    id: id.into(),
                    content: text.into(),
                    round: None,
                    model_turn_id: None,
                    interrupted: false,
                    sources: Vec::new(),
                    created_at: "2026-07-14T00:00:01Z".into(),
                }],
                text.into(),
                AgentLiveStatus::Idle,
                &ModelUsage::default(),
                0,
                None,
            );
        };

        let request = run_request(ProviderFamily::OpenaiResponses);
        let state = AppState::default();
        let mut history = Vec::<ContextItem>::new();
        let mut generated = vec![tool_context(&tool_execution_for("call-spawn", "agent_spawn"), 1)];
        let spawn_id = generated[0].id().to_owned();
        shared.record_call_context("call-spawn", &spawn_id);
        settle("初版结论", "answer-1");
        let checkpoint = |history: &mut Vec<ContextItem>, generated: &mut Vec<ContextItem>| {
            checkpoint_terminal_agent_records(
                &pool,
                &request.conversation_id,
                &request.workspace_path,
                &state,
                &discard_event,
                1,
                history.as_mut_slice(),
                generated.as_mut_slice(),
                &HashMap::new(),
            );
        };
        checkpoint(&mut history, &mut generated);
        assert!(
            matches!(&generated[0], ContextItem::Tool { subagent: Some(_), .. }),
            "the spawn card carries the record while it is the latest call"
        );

        shared.begin_turn("call-followup");
        generated.push(tool_context(
            &tool_execution_for("call-followup", "followup_task"),
            2,
        ));
        let followup_id = generated[1].id().to_owned();
        shared.record_call_context("call-followup", &followup_id);
        settle("修订后的结论", "answer-2");
        checkpoint(&mut history, &mut generated);

        let carriers = generated
            .iter()
            .filter(|context| {
                matches!(context, ContextItem::Tool { subagent: Some(record), .. }
                    if record.name.as_deref() == Some("a1"))
            })
            .map(|context| context.id().to_owned())
            .collect::<Vec<_>>();
        assert_eq!(
            carriers,
            vec![followup_id],
            "only the latest call may carry the record after a continuation"
        );
    }

    #[test]
    fn queued_mailbox_messages_are_delivered_before_the_next_model_round() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(listener, vec![responses_text_output("收到消息后的回答")]);

        let workspace = tempfile::tempdir().unwrap();
        let mut request = loop_request_for(address, workspace.path());
        let mailbox = Arc::new(crate::agents::AgentMailbox::default());
        mailbox.push("排队中的主代理消息".into());
        request.agent_mailbox = AgentMailboxHandle(Some(Arc::clone(&mailbox)));

        let response =
            run_model(request, &AppState::default(), &discard_event, &approve_tool).unwrap();
        let captured = server.join().unwrap();

        assert!(mailbox.is_empty());
        assert!(
            captured[0].contains("排队中的主代理消息"),
            "queued message must be part of the model request"
        );
        assert!(matches!(
            response.contexts.first(),
            Some(ContextItem::User { content, .. }) if content == "排队中的主代理消息"
        ));
    }

    #[test]
    fn user_steer_preserves_queue_identity_and_acknowledges_actual_delivery() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(listener, vec![responses_text_output("已按引导处理")]);

        let workspace = tempfile::tempdir().unwrap();
        let mut request = loop_request_for(address, workspace.path());
        let mailbox = Arc::new(crate::agents::AgentMailbox::default());
        mailbox.push_message(crate::agents::MailboxMessage {
            id: Some("queued-user-1".into()),
            content: "先检查失败日志".into(),
            images: Vec::new(),
            created_at: Some("2026-07-24T00:00:00Z".into()),
        });
        request.steer_mailbox = AgentMailboxHandle(Some(Arc::clone(&mailbox)));
        let events = Mutex::new(Vec::<ModelStreamEvent>::new());
        let sink = |event: ModelStreamEvent| {
            events
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .push(event);
            Ok(())
        };

        let response = run_model(request, &AppState::default(), &sink, &approve_tool).unwrap();
        let captured = server.join().unwrap();

        assert!(mailbox.is_empty());
        assert!(captured[0].contains("先检查失败日志"));
        assert!(events
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .iter()
            .any(|event| matches!(
                event,
                ModelStreamEvent::UserInputReceived {
                    round: 1,
                    id,
                    content,
                    images,
                    created_at,
                } if id == "queued-user-1"
                    && content == "先检查失败日志"
                    && images.is_empty()
                    && created_at == "2026-07-24T00:00:00Z"
            )));
        assert!(response.contexts.iter().any(|context| matches!(
            context,
            ContextItem::User {
                id,
                content,
                created_at,
                ..
            } if id == "queued-user-1"
                && content == "先检查失败日志"
                && created_at == "2026-07-24T00:00:00Z"
        )));
    }

    #[test]
    fn subagent_update_follows_the_parent_english_tool_defaults() {
        let mut parent = run_request(ProviderFamily::OpenaiResponses);
        parent.tools =
            catalog::tool_catalog_for_language(crate::model::ResolvedLanguage::EnUs);

        let child = agent_child_template(&parent);
        let update = child
            .tools
            .iter()
            .find(|tool| tool.name == SUBAGENT_UPDATE_TOOL)
            .expect("child template must inject the progress-update tool");

        assert_eq!(update.label, "Update");
        assert_eq!(update.description, "");
        let schema = tool_schema(update, true, &crate::prompt_profile::PromptProfile::builtin_english());
        assert_eq!(
            schema["description"],
            json!(
                "Send one short progress note to the parent agent; the final conclusion still has to be in the last reply."
            )
        );
        assert_eq!(schema["properties"]["message"]["maxLength"], json!(4000));
        assert_eq!(update.parameters.len(), 1);
        assert_eq!(update.parameters[0].label, "Progress");
        assert_eq!(
            update.parameters[0].help.as_deref(),
            Some("Describe current progress, important findings, or the next step.")
        );
    }

    /// A parent that can be forked AND restored. `restore_conversation_fork_binding`
    /// re-runs the autoload, so a parent that carried no memory snapshot at fork
    /// time trips the "a snapshot appeared where there was none" guard on
    /// restore. Giving the parent its real autoloaded prompt and lease puts the
    /// restore path on its (Some, Some) arm, which is the one that matters here.
    fn forkable_parent(root: &Path, _state: &AppState, model_id: &str) -> RunModelRequest {
        // A forkable parent is now simply a conversation with memory enabled
        // and a workspace on disk. The block it carries is read from those two
        // directories rather than issued by a store, so there is no lease or
        // snapshot receipt to mint here.
        let workspace = root.join("workspace");
        std::fs::create_dir_all(workspace.join(".mework/memory")).unwrap();
        std::fs::write(workspace.join(".mework/MEWORK.md"), "父对话常驻指令").unwrap();

        let mut parent = run_request(ProviderFamily::OpenaiResponses);
        parent.model.id = model_id.to_owned();
        parent.app_data_path = root.to_string_lossy().into_owned();
        parent.workspace_path = workspace.to_string_lossy().into_owned();
        parent.global_memory_enabled = true;
        parent.project_memory_enabled = true;
        let prompt = run_memory_roots(&parent)
            .render_context(&parent.prompt_profile)
            .expect("an enabled tier with instructions renders a block");
        parent.ephemeral_contexts.push(ContextItem::User {
            id: "forkable-parent-memory".into(),
            content: prompt,
            images: Vec::new(),
            created_at: "2026-08-01T00:00:00Z".into(),
        });
        parent.memory_context_id = Some("forkable-parent-memory".into());
        parent
    }

    #[test]
    fn a_restored_fork_drops_the_memory_tools_of_a_tier_turned_off_since_it_was_created() {
        // Fork creation snapshots the exact memory tool names the fork held.
        // The two tier switches are live conversation policy, so a fork must
        // not be able to bring a disabled tier back — and, just as important,
        // the per-turn fence has to expect the same narrowed set, or the fork
        // would restore cleanly and then fail its own validation next round.
        let root = tempfile::tempdir().unwrap();
        let state = AppState::default();
        let parent = forkable_parent(root.path(), &state, "fork-model");
        let mut parent = parent;
        parent.tools = catalog::tool_catalog();
        parent.enabled_tools = crate::mework_memory::MEMORY_TOOL_NAMES
            .iter()
            .map(|name| (*name).to_string())
            .collect();

        let mut child = agent_child_template(&parent);
        inherit_parent_model_memory_for_fork(&parent, &mut child, &state).unwrap();
        let binding = child
            .fork_model_binding
            .clone()
            .expect("forking mints a binding");
        assert_eq!(binding.memory_tool_names.len(), 6);

        // The conversation turns global memory off; the fork is restored.
        let mut restored = agent_child_template(&parent);
        restored.global_memory_enabled = false;
        restored.project_memory_enabled = true;
        restore_conversation_fork_binding(&mut restored, &binding).unwrap();
        let held = restored
            .enabled_tools
            .iter()
            .filter(|name| is_memory_tool_name(name))
            .cloned()
            .collect::<BTreeSet<_>>();
        assert_eq!(
            held,
            crate::mework_memory::PROJECT_MEMORY_TOOL_NAMES
                .into_iter()
                .map(str::to_owned)
                .collect::<BTreeSet<_>>()
        );
        // The fence agrees with what restore actually handed out.
        validate_current_fork_binding(&restored).unwrap();

        // Both tiers off: the fork carries no memory tools and no block.
        let mut dark = agent_child_template(&parent);
        dark.global_memory_enabled = false;
        dark.project_memory_enabled = false;
        restore_conversation_fork_binding(&mut dark, &binding).unwrap();
        assert!(!dark.enabled_tools.iter().any(|name| is_memory_tool_name(name)));
        assert!(host_memory_prompt_content(&dark).unwrap().is_none());
        validate_current_fork_binding(&dark).unwrap();
    }

    /// The child addendum follows the parent prompt profile, at both production
    /// call sites. Tool-catalogue language does not control injected text.
    #[test]
    fn both_child_prompt_call_sites_take_the_language_from_the_parent_profile() {
        let mut zh_parent = run_request(ProviderFamily::OpenaiResponses);
        zh_parent.system_prompt = "Parent prompt.".into();
        zh_parent.enabled_tools = vec!["read".into()];
        zh_parent.tools = catalog::tool_catalog_for_language(ResolvedLanguage::EnUs);
        zh_parent.prompt_profile = Arc::new(PromptProfile::builtin_chinese());
        let mut en_parent = zh_parent.clone();
        en_parent.prompt_profile = Arc::new(PromptProfile::builtin_english());

        // Call site 1: `agent_child_template`, the ordinary/fork prompt.
        let zh_child = agent_child_template(&zh_parent).system_prompt;
        let en_child = agent_child_template(&en_parent).system_prompt;
        assert!(zh_child.contains("你是主代理派生的子代理"), "{zh_child}");
        assert!(en_child.contains("You are a child agent spawned by the main agent"), "{en_child}");
        assert!(zh_child.starts_with("Parent prompt.\n\n---\n\n"));
        assert!(en_child.starts_with("Parent prompt.\n\n---\n\n"));

        // Call site 2: `configure_named_agent_template` uses the same parent
        // profile rather than deriving text from the parent's tool catalogue.
        let (_directory, state, base_parent, definition) =
            named_agent_fixture(AgentDefinitionMemory::None);
        let document = current_agent_document(&base_parent, &state).unwrap();
        let named_prompt = |profile: Arc<PromptProfile>| {
            let mut parent = base_parent.clone();
            parent.prompt_profile = profile;
            let (binding, provider, model) =
                initial_agent_definition_binding(&parent, &document, &definition).unwrap();
            let mut child = agent_child_template(&parent);
            configure_named_agent_template(
                &parent,
                &mut child,
                &definition,
                binding,
                provider,
                model,
                &document.assets.web_search,
                AgentRunStart::Fresh,
            )
            .unwrap();
            child.system_prompt
        };
        let zh_named = named_prompt(Arc::new(PromptProfile::builtin_chinese()));
        let en_named = named_prompt(Arc::new(PromptProfile::builtin_english()));
        assert!(zh_named.contains("你是主代理派生的子代理"), "{zh_named}");
        assert!(en_named.contains("You are a child agent spawned by the main agent"), "{en_named}");
        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }



    #[test]
    fn named_agent_uses_the_parent_conversation_memory_locations() {
        let (directory, state, mut parent, definition) =
            named_agent_fixture(AgentDefinitionMemory::Project);
        parent.global_memory_enabled = true;
        parent.project_memory_enabled = true;
        let document = current_agent_document(&parent, &state).unwrap();
        let (binding, provider, model) =
            initial_agent_definition_binding(&parent, &document, &definition).unwrap();
        let mut child = agent_child_template(&parent);
        configure_named_agent_template(
            &parent,
            &mut child,
            &definition,
            binding,
            provider,
            model,
            &document.assets.web_search,
            AgentRunStart::Fresh,
        )
        .unwrap();

        // Memory belongs to the host-selected global/project locations, not to
        // an agent/model partition or an opaque lease — and the role's binding
        // picks WHICH location, so a `project` role gets exactly the three
        // project tools and none of the global ones.
        assert!(!child.global_memory_enabled);
        assert!(child.project_memory_enabled);
        let memory_tool_names = child
            .tools
            .iter()
            .filter(|tool| tool.category == ToolCategory::Memory)
            .map(|tool| tool.name.as_str())
            .collect::<BTreeSet<_>>();
        assert_eq!(
            memory_tool_names,
            crate::mework_memory::PROJECT_MEMORY_TOOL_NAMES
                .into_iter()
                .collect::<BTreeSet<_>>()
        );
        for name in crate::mework_memory::GLOBAL_MEMORY_TOOL_NAMES {
            assert!(!child.enabled_tools.iter().any(|enabled| enabled == name), "{name}");
        }
        assert!(child
            .tools
            .iter()
            .filter(|tool| tool.category == ToolCategory::Memory)
            .all(|tool| tool.parameters.iter().all(|parameter| {
                !matches!(
                    parameter.name.as_str(),
                    "scope" | "modelId" | "model_id" | "provider" | "workspace" | "agent"
                )
            })));

        refresh_named_agent_memory(&mut child, &state).unwrap();
        // No per-agent lease or host prompt is required in the location-owned
        // design; the definition fence remains the only named-agent check.
        validate_current_agent_definition(&child, &state).unwrap();
        let execution = execute_model_tool(
            &child,
            ToolCall {
                id: "agent-memory-create".into(),
                name: "create_project_memory".into(),
                input: serde_json::from_value(json!({
                    "name": "review-preferences",
                    "content": "Prefer evidence-backed reviews.",
                    "description": "Review preferences"
                }))
                .unwrap(),
            },
            &state,
            &|_, _, _| panic!("memory tools never request filesystem approval"),
            false,
        );
        assert!(execution.result.success, "{}", execution.result.output);
        assert_eq!(
            std::fs::read_to_string(directory.path().join(".mework/memory/review-preferences.md"))
                .unwrap(),
            "Prefer evidence-backed reviews."
        );
        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }

    #[test]
    fn a_named_agent_memory_binding_selects_one_tier_and_never_widens_the_parent() {
        // `user` means the global tier, `project`/`local` mean the project
        // tier, `none` means neither. The parent's own two switches are the
        // ceiling: a role cannot open a tier the conversation left off.
        let configure = |binding_memory: AgentDefinitionMemory,
                         parent_global: bool,
                         parent_project: bool| {
            let (directory, state, mut parent, definition) = named_agent_fixture(binding_memory);
            parent.global_memory_enabled = parent_global;
            parent.project_memory_enabled = parent_project;
            let document = current_agent_document(&parent, &state).unwrap();
            let (binding, provider, model) =
                initial_agent_definition_binding(&parent, &document, &definition).unwrap();
            let mut child = agent_child_template(&parent);
            configure_named_agent_template(
                &parent,
                &mut child,
                &definition,
                binding,
                provider,
                model,
                &document.assets.web_search,
                AgentRunStart::Fresh,
            )
            .unwrap();
            state.document_store.flush(Duration::from_secs(10)).unwrap();
            drop(directory);
            child
        };
        let granted = |child: &RunModelRequest| {
            child
                .enabled_tools
                .iter()
                .filter(|name| is_memory_tool_name(name))
                .cloned()
                .collect::<BTreeSet<_>>()
        };
        let names = |trio: [&'static str; 3]| {
            trio.into_iter().map(str::to_owned).collect::<BTreeSet<_>>()
        };

        // Both tiers on at the parent: the binding alone decides.
        let user = configure(AgentDefinitionMemory::User, true, true);
        assert!(user.global_memory_enabled && !user.project_memory_enabled);
        assert_eq!(
            granted(&user),
            names(crate::mework_memory::GLOBAL_MEMORY_TOOL_NAMES)
        );
        for local_like in [AgentDefinitionMemory::Project, AgentDefinitionMemory::Local] {
            let child = configure(local_like, true, true);
            assert!(!child.global_memory_enabled && child.project_memory_enabled);
            assert_eq!(
                granted(&child),
                names(crate::mework_memory::PROJECT_MEMORY_TOOL_NAMES)
            );
        }
        let none = configure(AgentDefinitionMemory::None, true, true);
        assert!(!none.memory_enabled());
        assert!(granted(&none).is_empty());

        // The parent is the ceiling: a `user` role in a conversation with
        // global memory off gets nothing, even though project memory is on.
        let starved = configure(AgentDefinitionMemory::User, false, true);
        assert!(!starved.memory_enabled());
        assert!(granted(&starved).is_empty());
    }

    #[test]
    fn named_agent_definition_revision_is_rechecked_before_every_provider_attempt() {
        let (directory, state, parent, definition) =
            named_agent_fixture(AgentDefinitionMemory::User);
        let document = current_agent_document(&parent, &state).unwrap();
        let (binding, provider, model) =
            initial_agent_definition_binding(&parent, &document, &definition).unwrap();
        let mut child = agent_child_template(&parent);
        configure_named_agent_template(
            &parent,
            &mut child,
            &definition,
            binding,
            provider,
            model,
            &document.assets.web_search,
            AgentRunStart::Fresh,
        )
        .unwrap();
        refresh_named_agent_memory(&mut child, &state).unwrap();
        validate_current_agent_definition(&child, &state).unwrap();

        let mut changed = (*document).clone();
        conversation_agent_definitions_mut(&mut changed)[0].revision = 2;
        conversation_agent_definitions_mut(&mut changed)[0].effort =
            Some(crate::model::ReasoningEffort::High);
        state
            .document_store
            .commit(&directory.path().join("document.v1.json"), changed)
            .unwrap();
        // Field-by-field comparison detects revised definitions without an identity ledger.
        let validation_error = validate_current_agent_definition(&child, &state).unwrap_err();
        assert!(validation_error.contains("was replaced, revised, or had its memory scope changed"), "{validation_error}");
        let fence_error = current_agent_definition_authority(&child, &state, "Retry").unwrap_err();
        assert!(fence_error.contains("was replaced, revised, or had its memory scope changed"), "{fence_error}");
        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }

    /// A request rejected by the authorization fence never reaches `submit`.
    ///
    /// Rejected attempts must fail before launching the sidecar, and both read locks
    /// must be released after validation.
    fn assert_blocked_before_submit(exhausted: &ExhaustedRequest, expected: &str) {
        assert_eq!(exhausted.attempts, 1);
        let ModelRequestError::Fatal(message) = &exhausted.error else {
            panic!("被栅栏挡下必须是 Fatal：{:?}", exhausted.error);
        };
        assert_eq!(message, expected);
        assert!(
            !message.contains("AI SDK 侧车"),
            "走到拉起侧车这一步就说明栅栏没挡住：{message}"
        );
    }

    /// A minimal step request whose address must never be contacted.
    fn fence_step() -> crate::aisdk::protocol::StepRequest {
        step_request(&run_request(ProviderFamily::OpenaiResponses))
    }

    #[test]
    fn provider_attempt_definition_fence_blocks_revoked_named_agent_before_http_send() {
        let state = AppState::default();
        let events = Mutex::new(Vec::new());
        let sink = |event: ModelStreamEvent| {
            events.lock().unwrap().push(event);
            Ok(())
        };

        let exhausted = post_model_request_with_validator(
            &fence_step(),
            None,
            9,
            &sink,
            Some(state.definition_authority_lock.as_ref()),
            &|| Err("命名 Agent 定义已被撤销".into()),
            None,
            &|| Ok(()),
            None,
        )
        .unwrap_err();

        assert_blocked_before_submit(&exhausted, "命名 Agent 定义已被撤销");
        // Validation precedes diagnostic dumping, so no event is emitted.
        assert!(events.into_inner().unwrap().is_empty());
        // The rejected attempt must release the read lock.
        assert!(state.definition_authority_lock.try_write().is_ok());
    }



    #[test]
    fn stop_hook_definition_fence_revalidates_after_revocation_before_side_effects() {
        let (directory, state, parent, definition) =
            named_agent_fixture(AgentDefinitionMemory::None);
        let document = current_agent_document(&parent, &state).unwrap();
        let (binding, provider, model) =
            initial_agent_definition_binding(&parent, &document, &definition).unwrap();
        let mut child = agent_child_template(&parent);
        configure_named_agent_template(
            &parent,
            &mut child,
            &definition,
            binding,
            provider,
            model,
            &document.assets.web_search,
            AgentRunStart::Fresh,
        )
        .unwrap();
        validate_current_agent_definition(&child, &state).unwrap();

        // Model the exact response/Stop boundary: the provider request no
        // longer owns the read fence, a definition writer commits revocation,
        // and the Stop path is queued behind that writer. Once released, the
        // Stop path must revalidate and reject before its side-effect closure.
        let definition_writer = state.definition_authority_lock.write().unwrap();
        let mut revoked = (*document).clone();
        conversation_agent_definitions_mut(&mut revoked)[0].deleted = true;
        conversation_agent_definitions_mut(&mut revoked)[0].enabled = false;
        conversation_agent_definitions_mut(&mut revoked)[0].revision += 1;
        state
            .document_store
            .commit(&directory.path().join("document.v1.json"), revoked)
            .unwrap();

        let side_effect_ran = Arc::new(AtomicBool::new(false));
        let result = std::thread::scope(|scope| {
            let side_effect_ran = Arc::clone(&side_effect_ran);
            let child = &child;
            let state = &state;
            let handle = scope.spawn(move || {
                let _authority = current_agent_definition_authority(child, state, "Stop 钩子测试")?;
                side_effect_ran.store(true, Ordering::SeqCst);
                Ok::<(), String>(())
            });
            drop(definition_writer);
            handle.join().unwrap()
        });

        let error = result.unwrap_err();
        assert!(
            error.contains("Trusted named-agent definition")
                || error.contains("was deleted")
                || error.contains("does not exist")
                || error.contains("revision"),
            "{error}"
        );
        assert!(
            !side_effect_ran.load(Ordering::SeqCst),
            "revoked named agent must not execute the Stop side effect"
        );
        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }

