    #[test]
    fn agent_type_resolution_folds_separators_but_never_beats_an_exact_name() {
        let (directory, state, parent, user) = named_agent_fixture(AgentDefinitionMemory::None);
        let document = current_agent_document(&parent, &state).unwrap();
        let mut changed = (*document).clone();
        set_conversation_agent_definitions(&mut changed, vec![
            AgentDefinition {
                name: "code-reviewer".into(),
                ..user.clone()
            },
            AgentDefinition {
                name: "codereviewer".into(),
                ..user.clone()
            },
        ]);
        state
            .document_store
            .commit(&directory.path().join("document.v1.json"), changed)
            .unwrap();
        let document = current_agent_document(&parent, &state).unwrap();

        // An exact hit never consults the folded pass, even though the folded
        // form is ambiguous.
        assert_eq!(
            resolve_agent_definition(&document, request_agent_definitions(&document, &parent), &parent.workspace_id, "codereviewer")
                .unwrap()
                .name,
            "codereviewer"
        );
        // No exact name, and folding matches both — refuse rather than guess.
        let ambiguous =
            resolve_agent_definition(&document, request_agent_definitions(&document, &parent), &parent.workspace_id, "code_reviewer").unwrap_err();
        assert!(ambiguous.contains("code-reviewer"), "{ambiguous}");
        assert!(ambiguous.contains("codereviewer"), "{ambiguous}");

        state.document_store.flush(Duration::from_secs(10)).unwrap();
    }

