    /// A child result that completes while the model is busy reaches the timeline
    /// once, is read at a later round boundary, and is never re-folded on replay.
    ///
    /// The sink gate, rather than intermediary rounds, establishes ordering: each
    /// post-spawn round waits for the child's `idle` status delta on the session
    /// task surface.
    #[test]
    fn an_unwaited_child_result_reaches_the_timeline_once_and_the_next_turn_sees_it() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_routed_json(
            listener,
            vec![
                // Round 1: spawn and deliberately never wait.
                json!({
                    "model": "model-test",
                    "status": "completed",
                    "output": [
                        {"type":"function_call","status":"completed","call_id":"call-spawn","name":"agent_spawn",
                            "arguments": json!({"prompt":"后台审查","name":"a1"}).to_string()}
                    ],
                    "usage": {"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
                // Rounds 2-4: unrelated busywork, no task_wait anywhere.
                json!({
                    "model": "model-test",
                    "status": "completed",
                    "output": [
                        {"type":"function_call","status":"completed","call_id":"call-task","name":"todo",
                            "arguments": json!({"action":"create","subject":"别的事","description":"与子代理无关"}).to_string()}
                    ],
                    "usage": {"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
                json!({
                    "model": "model-test",
                    "status": "completed",
                    "output": [
                        {"type":"function_call","status":"completed","call_id":"call-update","name":"todo",
                            "arguments": json!({"action":"update","taskId":"task-1","status":"in_progress"}).to_string()}
                    ],
                    "usage": {"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
                json!({
                    "model": "model-test",
                    "status": "completed",
                    "output": [
                        {"type":"function_call","status":"completed","call_id":"call-get","name":"todo",
                            "arguments": json!({"action":"get","taskId":"task-1"}).to_string()}
                    ],
                    "usage": {"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
                // Round 5: the parent ends without ever waiting.
                responses_text_output("主代理自顾自结束"),
            ],
            vec![responses_text_output("子代理结论：接口无回归")],
        );
        let workspace = tempfile::tempdir().unwrap();
        let request = loop_request_for(address, workspace.path());
        let state = AppState::default();
        // Gate each parent round on the child's `idle` status delta from the
        // session task surface. This makes completion before the fold an ordering
        // guarantee rather than an HTTP-timing race.
        let child_idle = Arc::new((Mutex::new(false), std::sync::Condvar::new()));
        {
            let child_idle = Arc::clone(&child_idle);
            state.register_task_surface(
                &request.conversation_id,
                Arc::new(crate::state::TaskSurface {
                    sink: Arc::new(move |event: ModelStreamEvent| {
                        if let ModelStreamEvent::SubagentDelta {
                            channel: SubagentChannel::Status,
                            ref delta,
                            ..
                        } = event
                        {
                            if delta == "idle" {
                                *child_idle.0.lock().unwrap() = true;
                                child_idle.1.notify_all();
                            }
                        }
                        Ok(())
                    }),
                    approve: Arc::new(
                        |_: &ToolExecutionRequest,
                         _: &ToolDescriptor,
                         _: ApprovalRequester<'_>,
                         _: Option<&std::sync::atomic::AtomicBool>| Ok(true),
                    ),
                }),
            );
        }
        let gate = |event: ModelStreamEvent| -> Result<(), String> {
            // Every parent round after the spawn waits for the child, so the
            // fold at a later round boundary always observes an undelivered
            // Completed result.
            if let ModelStreamEvent::ToolCallAnnounced { ref call_id, .. } = event {
                if call_id != "call-spawn" {
                    let mut idle = child_idle.0.lock().unwrap();
                    while !*idle {
                        let (next, timeout) = child_idle
                            .1
                            .wait_timeout(idle, Duration::from_secs(30))
                            .unwrap();
                        assert!(!timeout.timed_out(), "child never reported idle");
                        idle = next;
                    }
                }
            }
            Ok(())
        };
        let response = run_model(request.clone(), &state, &gate, &approve_tool).unwrap();
        server.join().unwrap();

        let notifications: Vec<_> = response
            .contexts
            .iter()
            .filter_map(|context| match context {
                ContextItem::Tool {
                    id,
                    tool_name,
                    result,
                    ..
                } if id.starts_with("ctx_agent-result_") && tool_name == TASK_WAIT_TOOL => {
                    Some(result.output.clone())
                }
                _ => None,
            })
            .collect();
        assert_eq!(notifications.len(), 1, "exactly one folded delivery");
        assert!(
            notifications[0].contains(&format!(
                "[a1 · {}]",
                PromptKey::TaskStatusCompleted.builtin_en()
            )),
            "{}",
            notifications[0]
        );
        assert!(
            notifications[0].contains("子代理结论：接口无回归"),
            "{}",
            notifications[0]
        );
        // Which boundary folds it (a mid-turn round or the turn tail) is
        // scheduler timing; in-turn model visibility is the same
        // `request.contexts` push the steer drain relies on, and MODEL
        // visibility is asserted deterministically on turn 2's wire below.
        // The record still reproduces the agent tree beside the notification.
        let record = response
            .contexts
            .iter()
            .find_map(|context| match context {
                ContextItem::Tool {
                    tool_name,
                    subagent: Some(record),
                    ..
                } if tool_name == "agent_spawn" => Some(record),
                _ => None,
            })
            .expect("spawn record");
        assert_eq!(record.status, SubagentRunStatus::Completed);

        // Turn 2: the persisted notification reaches the next turn's model
        // through plain history, and nothing re-folds on replay.
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(listener, vec![responses_text_output("好的")]);
        let mut second = loop_request_for(address, workspace.path());
        second.contexts = request.contexts.clone();
        second.contexts.extend(response.contexts.clone());
        second.contexts.push(ContextItem::User {
            id: "ctx_turn2_prompt".into(),
            content: "继续".into(),
            images: Vec::new(),
            created_at: Utc::now().to_rfc3339(),
        });
        let second_response = run_model(second, &state, &discard_event, &approve_tool).unwrap();
        let captured = server.join().unwrap();
        assert!(
            captured[0].contains(&format!(
                "[a1 · {}]",
                PromptKey::TaskStatusCompleted.builtin_en()
            )),
            "the next turn's model must see the persisted notification"
        );
        assert!(
            !second_response
                .contexts
                .iter()
                .any(|context| context.id().starts_with("ctx_agent-result_")),
            "a replayed timeline must not re-fold"
        );
    }

    /// If a child result settles after the parent finishes a text-only round, the
    /// parent must open a delivery round. Server-side barriers ensure the result misses
    /// the prior fold and is settled before the completion decision.
    #[test]
    fn a_result_landing_after_the_last_round_forces_a_delivery_round() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();

        #[derive(Default)]
        struct Sequencer {
            parent_requests: usize,
            child_idle: bool,
        }
        let sequencer: Arc<(Mutex<Sequencer>, std::sync::Condvar)> = Arc::default();
        let parent_bodies: Arc<Mutex<Vec<(usize, String)>>> = Arc::default();

        let parent_responses = vec![
            // Round 1: spawn and deliberately never wait.
            json!({
                "model": "model-test",
                "status": "completed",
                "output": [
                    {"type":"function_call","status":"completed","call_id":"call-spawn","name":"agent_spawn",
                        "arguments": json!({"prompt":"后台审查","name":"a1"}).to_string()}
                ],
                "usage": {"input_tokens":1,"output_tokens":1,"total_tokens":2}
            }),
            // Round 2: the model believes it is done (no tool calls).
            responses_text_output("我先总结到这里"),
            // Round 3: the forced delivery round, after the fold reached the
            // model.
            responses_text_output("收到子代理结论,补记归档"),
        ];
        let child_response = responses_text_output("子代理结论:接口无回归");

        let server = {
            let sequencer = Arc::clone(&sequencer);
            let parent_bodies = Arc::clone(&parent_bodies);
            thread::spawn(move || {
                let mut handlers = Vec::new();
                for _ in 0..4 {
                    let (mut stream, _) = listener.accept().unwrap();
                    let body = read_http_request_with_body(&mut stream);
                    let sequencer = Arc::clone(&sequencer);
                    if body.contains("You are a child agent spawned by the main agent")
                    || body.contains("你是主代理派生的子代理")
                {
                        let response = child_response.clone();
                        handlers.push(thread::spawn(move || {
                            // Hold the child response until the parent has issued
                            // round 2, whose fold has already missed this result.
                            let (state, signal) = &*sequencer;
                            let mut guard = state.lock().unwrap();
                            while guard.parent_requests < 2 {
                                let (next, timeout) = signal
                                    .wait_timeout(guard, Duration::from_secs(30))
                                    .unwrap();
                                assert!(!timeout.timed_out(), "parent round 2 never arrived");
                                guard = next;
                            }
                            drop(guard);
                            write_json_response(&mut stream, "200 OK", &response);
                        }));
                    } else {
                        let ordinal = {
                            let (state, signal) = &*sequencer;
                            let mut guard = state.lock().unwrap();
                            guard.parent_requests += 1;
                            signal.notify_all();
                            guard.parent_requests
                        };
                        parent_bodies.lock().unwrap().push((ordinal, body));
                        let response = parent_responses[ordinal - 1].clone();
                        handlers.push(thread::spawn(move || {
                            if ordinal == 2 {
                                // Hold the parent round-2 response until the child
                                // settles, so the convergence decision observes its result.
                                let (state, signal) = &*sequencer;
                                let mut guard = state.lock().unwrap();
                                while !guard.child_idle {
                                    let (next, timeout) = signal
                                        .wait_timeout(guard, Duration::from_secs(30))
                                        .unwrap();
                                    assert!(!timeout.timed_out(), "child never reported idle");
                                    guard = next;
                                }
                                drop(guard);
                            }
                            write_json_response(&mut stream, "200 OK", &response);
                        }));
                    }
                }
                for handler in handlers {
                    handler.join().unwrap();
                }
            })
        };

        let workspace = tempfile::tempdir().unwrap();
        let request = loop_request_for(address, workspace.path());
        let state = AppState::default();
        // Child status deltas use the session task surface, not the parent run sink.
        {
            let sequencer = Arc::clone(&sequencer);
            state.register_task_surface(
                &request.conversation_id,
                Arc::new(crate::state::TaskSurface {
                    sink: Arc::new(move |event: ModelStreamEvent| {
                        if let ModelStreamEvent::SubagentDelta {
                            channel: SubagentChannel::Status,
                            ref delta,
                            ..
                        } = event
                        {
                            if delta == "idle" {
                                let (state, signal) = &*sequencer;
                                state.lock().unwrap().child_idle = true;
                                signal.notify_all();
                            }
                        }
                        Ok(())
                    }),
                    approve: Arc::new(
                        |_: &ToolExecutionRequest,
                         _: &ToolDescriptor,
                         _: ApprovalRequester<'_>,
                         _: Option<&std::sync::atomic::AtomicBool>| Ok(true),
                    ),
                }),
            );
        }
        let response = run_model(request, &state, &discard_event, &approve_tool).unwrap();
        server.join().unwrap();

        let parent_bodies = parent_bodies.lock().unwrap();
        assert_eq!(parent_bodies.len(), 3, "交付轮必须存在");
        let delivery_body = &parent_bodies
            .iter()
            .find(|(ordinal, _)| *ordinal == 3)
            .expect("delivery round request")
            .1;
        assert!(
            delivery_body.contains("子代理结论:接口无回归"),
            "交付轮的请求必须携带 fold 通知（2026-08-26 抬头删除后，锚是结果正文本身）"
        );
        let notifications: Vec<_> = response
            .contexts
            .iter()
            .filter(|context| context.id().starts_with(AGENT_RESULT_CONTEXT_ID_PREFIX))
            .collect();
        assert_eq!(notifications.len(), 1, "恰好一次 fold 通知");
    }

    /// S8 assertion (e): the nudge fires only for a run that owes a result, has
    /// not produced one, and has not already been reminded.
    #[test]
    fn the_no_call_nudge_is_offered_exactly_once_and_only_when_it_is_owed() {
        let plain = run_request(ProviderFamily::OpenaiResponses);
        let mut state = StructuredOutputTurnState::default();
        assert!(
            !state.needs_nudge(&plain),
            "a run with no schema is never nudged"
        );

        let mut bound = run_request(ProviderFamily::OpenaiResponses);
        bound.output_schema = Some(structured_output_schema());
        assert!(state.needs_nudge(&bound));
        state.nudged = true;
        assert!(!state.needs_nudge(&bound), "exactly once");

        let mut answered = StructuredOutputTurnState::default();
        answered.value = Some(json!({"verdict": "ok"}));
        assert!(
            !answered.needs_nudge(&bound),
            "a run that already answered has nothing to be reminded of"
        );
        assert!(bound
            .prompt_profile
            .text(PromptKey::SubagentStructuredOutputNudge)
            .contains(STRUCTURED_OUTPUT_TOOL));
    }

    #[test]
    fn subagent_update_is_child_only_and_absent_from_the_global_catalog() {
        assert!(!catalog::tool_catalog()
            .iter()
            .any(|tool| tool.name == SUBAGENT_UPDATE_TOOL));

        let mut main = run_request(ProviderFamily::OpenaiResponses);
        main.tools.push(subagent_update_descriptor(&main.prompt_profile));
        main.enabled_tools.push(SUBAGENT_UPDATE_TOOL.into());
        let main_execution = execute_model_tool(
            &main,
            ToolCall {
                id: "call-main-update".into(),
                name: SUBAGENT_UPDATE_TOOL.into(),
                input: serde_json::from_value(json!({"message":"伪造更新"})).unwrap(),
            },
            &AppState::default(),
            &approve_tool,
            false,
        );
        assert!(!main_execution.result.success);
        assert!(main_execution
            .result
            .output
            .contains("The update tool is only for a subagent reporting status to the main agent"));

        let mut child = main;
        child.subagent_depth = 1;
        let child_execution = execute_model_tool(
            &child,
            ToolCall {
                id: "call-child-update".into(),
                name: SUBAGENT_UPDATE_TOOL.into(),
                input: serde_json::from_value(json!({"message":"真实更新"})).unwrap(),
            },
            &AppState::default(),
            &approve_tool,
            false,
        );
        assert!(child_execution.result.success);
        assert_eq!(
            child_execution.result.output,
            PromptKey::SubagentUpdateAck.builtin_en()
        );
    }

    #[test]
    fn subagent_failures_stops_and_round_limits_are_persisted_distinctly() {
        assert_eq!(subagent_run_status(None), SubagentRunStatus::Completed);
        assert_eq!(
            subagent_run_status(Some("completed")),
            SubagentRunStatus::Completed
        );
        // A provider error is retryable; a deliberate stop is not; a ceiling
        // produced partial-but-valid output. Collapsing them lost all three.
        assert_eq!(
            subagent_run_status(Some("error")),
            SubagentRunStatus::Failed
        );
        for reason in ["subagent_round_limit", "hook_continuation_limit"] {
            assert_eq!(
                subagent_run_status(Some(reason)),
                SubagentRunStatus::RoundLimit,
                "{reason}"
            );
            // Round-limit reasons are a subset of the stop set, so the
            // classifier's arm order is load-bearing.
            assert!(model_stop_reason_is_stopped(reason), "{reason}");
        }
        for reason in [
            "hook_stopped",
            "agent_definition_revoked",
            "cancelled",
            "canceled",
            "stopped",
        ] {
            assert_eq!(
                subagent_run_status(Some(reason)),
                SubagentRunStatus::Stopped,
                "{reason}"
            );
            assert!(model_stop_reason_is_stopped(reason), "{reason}");
        }
        // The live→persisted mapping must not re-collapse what the classifier
        // just distinguished.
        for (live, persisted) in [
            (AgentLiveStatus::Idle, SubagentRunStatus::Completed),
            (AgentLiveStatus::Failed, SubagentRunStatus::Failed),
            (AgentLiveStatus::Stopped, SubagentRunStatus::Stopped),
            (AgentLiveStatus::RoundLimit, SubagentRunStatus::RoundLimit),
            (AgentLiveStatus::Interrupted, SubagentRunStatus::Interrupted),
            (AgentLiveStatus::Running, SubagentRunStatus::Interrupted),
        ] {
            assert_eq!(live.persisted(), persisted, "{live:?}");
        }
        // Legacy documents carry only the two original wire values.
        assert_eq!(
            serde_json::from_str::<SubagentRunStatus>("\"interrupted\"").unwrap(),
            SubagentRunStatus::Interrupted
        );
        assert_eq!(
            serde_json::to_string(&SubagentRunStatus::RoundLimit).unwrap(),
            "\"roundLimit\""
        );
        assert!(!model_stop_reason_is_stopped("hook_blocked"));
        assert!(!model_stop_reason_is_stopped("awaiting_user"));
    }

    #[test]
    fn web_search_input_is_one_self_contained_query_and_nothing_else() {
        let parse = |value: Value| parse_web_search_query(value.as_object().unwrap());

        assert!(parse(json!({}))
            .unwrap_err()
            .contains("web_search.query must be a non-empty string"));
        assert!(parse(json!({"query": "   "})).is_err());
        assert_eq!(parse(json!({"query": " claude 5 发布日期 "})).unwrap(), "claude 5 发布日期");

        // Reject unknown keys rather than silently dropping a model's requested objective.
        for legacy in ["objective", "output_format", "tool_guidance", "boundaries"] {
            assert!(
                parse(json!({"query": "x y", legacy: "x"})).is_err(),
                "{legacy} 必须作为未知键被拒绝"
            );
        }

        // Queries must be long enough to be useful and short enough to split
        // into separate searches.
        assert!(parse(json!({"query": "a"})).is_err());
        let oversized = "长".repeat(WEB_SEARCH_MAX_QUERY + 1);
        assert!(parse(json!({"query": oversized}))
            .unwrap_err()
            .contains("200"));

        // The native task body contains only this query; it receives no
        // conversation context.
        let task = web_search_native_task(&PromptProfile::builtin_english(), "claude 5 发布日期");
        assert!(task.contains("claude 5 发布日期"));
        assert!(!task.contains("outputFormat"));
    }

    #[test]
    fn web_fetch_input_only_accepts_absolute_http_urls() {
        let parse = |value: Value| parse_web_fetch_urls(value.as_object().unwrap());

        assert_eq!(
            parse(json!({"urls": [" https://a.example/x "]})).unwrap(),
            vec!["https://a.example/x".to_owned()]
        );
        assert!(parse(json!({})).is_err());
        assert!(parse(json!({"urls": []})).is_err());
        assert!(parse(json!({"urls": ["a.example"]})).is_err());
        // A `file://` target would read a local file. This assertion shares the
        // executor's `normalize_urls` rule rather than duplicating it.
        assert!(parse(json!({"urls": ["file:///etc/passwd"]})).is_err());
        assert!(parse(json!({"urls": [5]})).is_err());
        assert!(parse(json!({"urls": ["https://a.example"], "query": "x"})).is_err());
        let too_many: Vec<String> = (0..=crate::model::MAX_SEARCH_INPUTS)
            .map(|index| format!("https://a{index}.example"))
            .collect();
        assert!(parse(json!({"urls": too_many})).is_err());
    }

    /// Streaming and non-streaming parsers have separate allowlists. Streaming accepts
    /// server-tool input deltas and ignores text-block citation deltas.
    /// Server-tool content blocks are accepted but never become host `ToolCall`s:
    /// the host cannot execute them, and treating them as calls would make
    /// `pause_turn` a protocol conflict.
    /// `web_search` replays paused assistant content byte-for-byte, including
    /// `encrypted_content`; any changed key or field order is a rewrite.
    ///
    /// This helper directly drives the worker's prepare and perform core.
    #[test]
    fn native_search_zero_consumption_retains_pause_safety_limit() {
        for budget in [0, 3] {
            let listener = TcpListener::bind("127.0.0.1:0").unwrap();
            let address = listener.local_addr().unwrap();
            let server = thread::spawn(move || {
                let mut captured = Vec::new();
                for _ in 0..=MAX_ANTHROPIC_PAUSE_CONTINUATIONS {
                    let (mut stream, _) = listener.accept().unwrap();
                    captured.push(read_http_request_with_body(&mut stream));
                    let frames = [
                        json!({"type":"message_start","message":{"id":"pause_no_search","type":"message","role":"assistant","model":"model-test","content":[],"usage":{"input_tokens":1,"output_tokens":0}}}),
                        json!({"type":"message_delta","delta":{"stop_reason":"pause_turn","stop_sequence":null},"usage":{"output_tokens":0}}),
                        json!({"type":"message_stop"}),
                    ];
                    let sse = frames.iter().map(|frame| format!("event: {}\ndata: {frame}\n\n", frame["type"].as_str().unwrap())).collect::<String>();
                    write_sse_response(&mut stream, &sse);
                }
                captured
            });
            let workspace = tempfile::tempdir().unwrap();
            let mut request = loop_request_for(address, workspace.path());
            request.provider.family = ProviderFamily::Anthropic;
            request.web_search.backend = Some(SearchBackend::Native);
            request.web_search.max_searches_per_call = budget;
            let result = run_prepared_web_search_for_test(&request, "Search", &discard_event, 1);
            assert!(matches!(result, Err(AsyncToolError::Failed(ref error)) if error.contains("safety limit")), "{result:?}");
            let bodies = server.join().unwrap();
            assert_eq!(bodies.len(), MAX_ANTHROPIC_PAUSE_CONTINUATIONS + 1);
            for body in bodies {
                let json: Value = serde_json::from_str(body.split("\r\n\r\n").nth(1).unwrap_or(&body)).unwrap();
                if budget == 0 {
                    assert!(json["tools"][0].get("max_uses").is_none());
                } else {
                    assert_eq!(json["tools"][0]["max_uses"], budget);
                }
            }
        }
    }

    #[test]
    fn native_search_pause_continuations_share_one_finite_search_budget() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = thread::spawn(move || {
            let mut captured = Vec::new();
            for (round, ids) in [vec!["budget_a", "budget_b"], vec!["budget_a", "budget_c"]].iter().enumerate() {
                let (mut stream, _) = listener.accept().unwrap();
                captured.push(read_http_request_with_body(&mut stream));
                let mut frames = vec![json!({"type":"message_start","message":{
                    "id":format!("budget_msg_{round}"),"type":"message","role":"assistant","model":"model-test",
                    "content":[],"usage":{"input_tokens":1,"output_tokens":0}}})];
                let mut index = 0;
                for id in ids {
                    frames.extend([
                        json!({"type":"content_block_start","index":index,"content_block":{"type":"server_tool_use","id":id,"name":"web_search","input":{}}}),
                        json!({"type":"content_block_delta","index":index,"delta":{"type":"input_json_delta","partial_json":"{\"query\":\"facts\"}"}}),
                        json!({"type":"content_block_stop","index":index}),
                        json!({"type":"content_block_start","index":index+1,"content_block":{"type":"web_search_tool_result","tool_use_id":id,"content":[]}}),
                        json!({"type":"content_block_stop","index":index+1}),
                    ]);
                    index += 2;
                }
                frames.extend([
                    json!({"type":"content_block_start","index":index,"content_block":{"type":"text","text":""}}),
                    json!({"type":"content_block_delta","index":index,"delta":{"type":"text_delta","text":format!("BUDGET_RESULT_{round}")}}),
                    json!({"type":"content_block_stop","index":index}),
                    json!({"type":"message_delta","delta":{"stop_reason":"pause_turn","stop_sequence":null},"usage":{"output_tokens":3}}),
                    json!({"type":"message_stop"}),
                ]);
                let sse = frames.iter().map(|frame| format!("event: {}\ndata: {frame}\n\n", frame["type"].as_str().unwrap())).collect::<String>();
                write_sse_response(&mut stream, &sse);
            }
            captured
        });
        let workspace = tempfile::tempdir().unwrap();
        let mut request = loop_request_for(address, workspace.path());
        request.provider.family = ProviderFamily::Anthropic;
        request.web_search.backend = Some(SearchBackend::Native);
        request.web_search.max_searches_per_call = 3;
        let result = run_prepared_web_search_for_test(&request, "Search", &discard_event, 1).unwrap();
        let bodies = server.join().unwrap();
        assert_eq!(bodies.len(), 2);
        for (body, expected) in bodies.iter().zip([3, 1]) {
            let json: Value = serde_json::from_str(body.split("\r\n\r\n").nth(1).unwrap_or(body)).unwrap();
            assert_eq!(json["tools"][0]["max_uses"], expected);
        }
        assert!(result.contains("BUDGET_RESULT_0") && result.contains("BUDGET_RESULT_1"), "{result}");
        assert!(result.contains("budget exhausted"), "{result}");
    }

    #[test]
    fn provider_search_sources_without_citations_are_persisted_and_footnoted() {
        for native in [false, true] {
            let listener = TcpListener::bind("127.0.0.1:0").unwrap();
            let address = listener.local_addr().unwrap();
            let mut fixture = responses_text_output(&"LONG_ANSWER ".repeat(4000));
            fixture["output"].as_array_mut().unwrap().insert(0, json!({
                "type":"web_search_call","id":"source_call","status":"completed",
                "action":{"type":"open_page","url":"https://retrieved.example/source"}
            }));
            let server = serve_json_sequence(listener, vec![fixture]);
            let workspace = tempfile::tempdir().unwrap();
            let mut request = loop_request_for(address, workspace.path());
            if native {
                request.web_search.backend = Some(SearchBackend::Native);
                let result = run_prepared_web_search_for_test(&request, "Search", &discard_event, 1).unwrap();
                let output: Value = serde_json::from_str(&result).unwrap();
                assert!(output["findings"].as_str().unwrap().contains("https://retrieved.example/source"));
            } else {
                let store = persisted_conversation_for(&request);
                let conversation_id = request.conversation_id.clone();
                run_model(request, &AppState::default(), &discard_event, &approve_tool).unwrap();
                let persisted = store.conversation(&conversation_id).unwrap().unwrap();
                assert!(persisted.contexts.iter().any(|item| matches!(item,
                    ContextItem::Assistant { sources, .. } if sources.iter().any(|source|
                        source.url.as_deref() == Some("https://retrieved.example/source")))));
            }
            assert_eq!(server.join().unwrap().len(), 1);
        }
    }

    #[test]
    fn native_search_findings_exclude_responses_commentary() {
        for answer in [Some("ANSWER_ONLY"), Some(""), Some("   "), None] {
            let listener = TcpListener::bind("127.0.0.1:0").unwrap();
            let address = listener.local_addr().unwrap();
            let mut output = vec![json!({"type":"message","id":"process","role":"assistant",
                "phase":"commentary","content":[{"type":"output_text","text":"PROCESS_ONLY"}]})];
            if let Some(text) = answer {
                output.push(json!({"type":"message","id":"answer","role":"assistant",
                    "phase":"final_answer","content":[{"type":"output_text","text":text}]}));
            }
            let server = serve_json_sequence(listener, vec![json!({"output":output,"usage":{"input_tokens":1,"output_tokens":1}})]);
            let workspace = tempfile::tempdir().unwrap();
            let mut parent = loop_request_for(address, workspace.path());
            parent.web_search.backend = Some(SearchBackend::Native);
            let result = run_prepared_web_search_for_test(&parent, "Search", &discard_event, 1);
            assert_eq!(server.join().unwrap().len(), 1);
            if answer.is_some_and(|text| !text.trim().is_empty()) {
                let output: Value = serde_json::from_str(&result.unwrap()).unwrap();
                assert!(output["findings"].as_str().unwrap().contains("ANSWER_ONLY"));
                assert!(!output["findings"].as_str().unwrap().contains("PROCESS_ONLY"));
            } else {
                assert!(matches!(result, Err(AsyncToolError::Failed(ref error)) if error.contains("returned no text")), "{result:?}");
            }
        }
    }

    fn run_prepared_web_search_for_test(
        parent: &RunModelRequest,
        query: &str,
        event_sink: &ModelEventSink<'_>,
        round: usize,
    ) -> Result<String, AsyncToolError> {
        let prepared = prepare_web_search_backend(parent, query.to_owned())
            .map_err(AsyncToolError::Failed)?;
        perform_prepared_web_search(&prepared, &parent.prompt_profile, event_sink, round)
    }

        /// A server search interrupted by `pause_turn` must resume automatically,
    /// replay paused assistant content byte-for-byte including `encrypted_content`,
    /// and produce one UI turn.
            #[test]
    fn a_web_search_call_holds_no_client_tools_and_carries_the_native_one() {
        let native_step_json = |request: &RunModelRequest| {
            let family = crate::aisdk::protocol::Family::for_format(request.provider.family);
            let step = crate::aisdk::step::build_step_request(
                request,
                &[],
                wire_history::project_full(family, &request.contexts),
                "https://api.test.invalid/v1",
                None,
                (MAX_ANTHROPIC_PAUSE_CONTINUATIONS as u32).saturating_add(1),
            )
            .expect("the isolated native-search step should build");
            serde_json::to_value(step).unwrap()
        };

        // Native search carries the conversation's configured `maxUses`; the
        // sidecar translates provider-specific tool dialects.
        let mut main = run_request(ProviderFamily::Anthropic);
        main.tools = catalog::tool_catalog();
        main.enabled_tools = main.tools.iter().map(|tool| tool.name.clone()).collect();
        main.web_search = crate::model::WebSearchSettings {
            max_searches_per_call: 4,
            backend: Some(SearchBackend::Native),
            ..Default::default()
        };
        let (provider, model) = resolve_native_search_endpoint(&main);
        // Search uses the conversation's provider and model, narrowing capabilities
        // and raising its output budget as needed.
        assert_eq!(provider.id, main.provider.id);
        assert_eq!(model.id, main.model.id);
        assert_eq!(provider.family, ProviderFamily::Anthropic);
        assert!(
            model.max_output_tokens.unwrap_or(0)
                >= crate::web_search::SEARCH_CALL_MAX_OUTPUT_TOKENS,
            "{:?}",
            model.max_output_tokens
        );
        assert!(!model.supports_vision());

        let search = web_search_request_template(&main, provider, model, "读取指定来源".into());
        assert!(search.native_search_call);
        // Native search is the only capability: no client tool is executed and
        // no second permission boundary exists.
        assert!(search.tools.is_empty());
        assert!(search.enabled_tools.is_empty());
        let search_step = native_step_json(&search);
        assert!(search_step.get("tools").is_none());
        assert_eq!(search_step["nativeSearch"], json!({ "maxUses": 4 }));
        assert_eq!(
            search_step["maxSteps"],
            json!((MAX_ANTHROPIC_PAUSE_CONTINUATIONS as u32).saturating_add(1))
        );

        // Ordinary conversations never receive native server tools, even for the
        // same provider.
        let main_step = step_json(&main);
        assert!(main_step.get("nativeSearch").is_none());
        assert!(!main_step["tools"].as_array().unwrap().is_empty());
        assert_eq!(main_step["maxSteps"], 1);

        // Responses use the same host contract; the sidecar absorbs provider
        // differences in `maxUses`.
        let mut responses = run_request(ProviderFamily::OpenaiResponses);
        responses.tools = catalog::tool_catalog();
        responses.enabled_tools = responses
            .tools
            .iter()
            .map(|tool| tool.name.clone())
            .collect();
        responses.web_search = crate::model::WebSearchSettings {
            max_searches_per_call: 7,
            backend: Some(SearchBackend::Native),
            ..Default::default()
        };
        let (provider, model) = resolve_native_search_endpoint(&responses);
        let search =
            web_search_request_template(&responses, provider, model, "读取指定来源".into());
        let search_step = native_step_json(&search);
        assert!(search_step.get("tools").is_none());
        assert_eq!(search_step["nativeSearch"], json!({ "maxUses": 7 }));

        let main_step = step_json(&responses);
        assert!(main_step.get("nativeSearch").is_none());
        let client_tools = main_step["tools"]
            .as_array()
            .expect("the main tier still advertises its client tools");
        assert!(!client_tools.is_empty());
        assert!(client_tools.iter().all(|tool| {
            tool.get("name").is_some()
                && tool.get("inputSchema").is_some()
                && tool.get("maxUses").is_none()
        }));

        // The catalog contract is `{query}`, not a delegated-objective protocol.
        let entry = responses
            .tools
            .iter()
            .find(|tool| tool.name == WEB_SEARCH_TOOL)
            .unwrap();
        let entry_schema = tool_schema(entry, true, &crate::prompt_profile::PromptProfile::builtin_english());
        assert!(entry_schema.pointer("/properties/query").is_some());
        assert!(entry_schema.pointer("/properties/objective").is_none());
    }


    /// Both unavailable-search cases must be actionable errors, never silent fallback
    /// to another search path.
    #[test]
    fn an_unusable_search_backend_is_a_repairable_refusal_not_a_fallback() {
        // An invalid explicit binding cannot resolve a backend, so the call site
        // rejects it directly.
        let mut main = run_request(ProviderFamily::OpenaiResponses);
        main.tools = catalog::tool_catalog();
        main.enabled_tools = main.tools.iter().map(|tool| tool.name.clone()).collect();
        main.web_search = crate::model::WebSearchSettings {
            max_searches_per_call: 0,
            backend: None,
            ..Default::default()
        };
        let call = ToolCall {
            id: "ws-dead".into(),
            name: WEB_SEARCH_TOOL.into(),
            input: serde_json::from_value(json!({ "query": "核对来源 A" })).unwrap(),
        };
        // An unavailable backend is locally determinable, so reject synchronously
        // before spawning a thread.
        let dispatch = dispatch_async_tool(
            &main,
            call,
            &approve_tool,
            true,
            JsonObject::new(),
            1,
        )
        .unwrap();
        let AsyncToolDispatch::Settled(execution) = dispatch else {
            panic!("配置拒绝必须就地了结，不得派发出一个注定失败的 worker");
        };
        assert!(
                !execution.result.success,
                "{}",
                execution.result.output
            );
        assert!(
            execution
                .result
                .output
                .contains("No usable search backend is configured"),
            "{}",
            execution.result.output
        );

        // A family without a native server tool produces a repairable error rather
        // than silently sending a request that cannot search.
        let mut chat = run_request(ProviderFamily::OpenaiChat);
        chat.tools = catalog::tool_catalog();
        chat.enabled_tools = chat.tools.iter().map(|tool| tool.name.clone()).collect();
        chat.web_search = crate::model::WebSearchSettings {
            max_searches_per_call: 0,
            backend: Some(SearchBackend::Native),
            ..Default::default()
        };
        let (provider, model) = resolve_native_search_endpoint(&chat);
        assert_eq!(provider.family, ProviderFamily::OpenaiChat);
        let search = web_search_request_template(&chat, provider, model, "读取来源".into());
        assert!(search.native_search_call);
        // The capability table, generated by the sidecar, is authoritative; the
        // host only determines whether the family has this path.
        assert!(
            !crate::web_search::family_supports_native_search(
                crate::aisdk::protocol::Family::for_format(search.provider.family)
            ),
            "Chat Completions 没有 provider-executed tool"
        );
        let call = ToolCall {
            id: "ws-chat".into(),
            name: WEB_SEARCH_TOOL.into(),
            input: serde_json::from_value(json!({ "query": "核对来源 A" })).unwrap(),
        };
        let dispatch = dispatch_async_tool(
            &chat,
            call,
            &approve_tool,
            true,
            JsonObject::new(),
            1,
        )
        .unwrap();
        let AsyncToolDispatch::Settled(execution) = dispatch else {
            panic!("配置拒绝必须就地了结，不得派发出一个注定失败的 worker");
        };
        assert!(
                !execution.result.success,
                "{}",
                execution.result.output
            );
        assert!(
            execution.result.output.contains("openai_chat family"),
            "拒绝要指名道姓说是哪个家族没有这条腿：{}",
            execution.result.output
        );
    }

    #[test]
