    /// The sidecar frame receives a normalized base URL; the host never constructs
    /// authorization headers. It enforces HTTPS except for loopback and removes pasted
    /// endpoint suffixes before framing the request.
    #[test]
    fn the_sidecar_frame_carries_the_normalized_base_url_and_no_host_auth_header() {
        let mut request = run_request(ProviderFamily::OpenaiResponses);
        request.provider.base_url = "https://api.example.test/custom/v1/responses".into();
        let base_url = provider_base_url(&request.provider)
            .unwrap()
            .expect("这一家的地址不是推导出来的");
        let step = step_request_with(&request, &[], base_url.as_str());
        let payload = serde_json::to_value(&step).unwrap();

        assert_eq!(payload["baseURL"], "https://api.example.test/custom/v1");
        // `baseUrl` uses serde camelCase, while the sidecar requires `baseURL`.
        assert!(payload.get("baseUrl").is_none());
        // The host does not construct authorization headers; the key is a separate
        // field and AI SDK adds the family-specific header.
        assert!(payload.get("headers").is_none());
        assert!(payload.get("apiKey").is_none());
        assert!(!payload.to_string().to_ascii_lowercase().contains("authorization"));

        // Plain HTTP is permitted only for loopback endpoints.
        request.provider.base_url = "http://api.example.test/v1".into();
        assert!(provider_base_url(&request.provider).is_err());
        request.provider.base_url = "http://127.0.0.1:8000/v1".into();
        assert!(provider_base_url(&request.provider).is_ok());
    }


