    #[test]
    fn mandatory_mcp_interaction_cannot_be_bypassed_by_full_access_or_hook_allow() {
        for level in [
            SecurityLevel::Plan,
            SecurityLevel::RequestApproval,
            SecurityLevel::AllowEdits,
            SecurityLevel::FullAccess,
        ] {
            for hook_allows in [false, true] {
                assert!(mcp_requires_native_approval(level, hook_allows, true));
            }
        }

        assert!(!mcp_requires_native_approval(
            SecurityLevel::FullAccess,
            false,
            false,
        ));
        assert!(!mcp_requires_native_approval(
            SecurityLevel::RequestApproval,
            true,
            false,
        ));
        assert!(mcp_requires_native_approval(
            SecurityLevel::RequestApproval,
            false,
            false,
        ));
    }

    #[test]
    fn hook_ask_survives_full_access_and_permission_hook_allow() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(
            listener,
            vec![
                json!({
                    "model": "model-test",
                    "status": "completed",
                    "output": [{
                        "type":"function_call",
                        "status":"completed",
                        "call_id":"call-agent-list",
                        "name":"task_list",
                        "arguments":"{}"
                    }],
                    "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}
                }),
                responses_text_output("done"),
            ],
        );

        let workspace = tempfile::tempdir().unwrap();
        let mut request = loop_request_for(address, workspace.path());
        request.security_level = SecurityLevel::FullAccess;
        #[cfg(windows)]
        let ask_command =
            r#"'{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"ask"}}'"#;
        #[cfg(not(windows))]
        let ask_command = r#"printf '%s' '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"ask"}}'"#;
        #[cfg(windows)]
        let command = r#"'{"hookSpecificOutput":{"hookEventName":"PermissionRequest","decision":{"behavior":"allow"}}}'"#;
        #[cfg(not(windows))]
        let command = r#"printf '%s' '{"hookSpecificOutput":{"hookEventName":"PermissionRequest","decision":{"behavior":"allow"}}}'"#;
        request.active_hooks = vec![
            HookDefinition {
                id: "ask-agent-list".into(),
                name: "Ask for agent list".into(),
                event: HookEvent::PreToolUse,
                matcher: Some("^task_list$".into()),
                command: ask_command.into(),
                command_windows: None,
                status_message: None,
                enabled: true,
                timeout_ms: 5_000,
            },
            HookDefinition {
                id: "allow-agent-list".into(),
                name: "Allow agent list".into(),
                event: HookEvent::PermissionRequest,
                matcher: Some("^task_list$".into()),
                command: command.into(),
                command_windows: None,
                status_message: None,
                enabled: true,
                timeout_ms: 5_000,
            },
        ];

        let approvals = std::sync::atomic::AtomicUsize::new(0);
        let response = run_model(
            request,
            &AppState::default(),
            &discard_event,
            &|execution, descriptor, _| {
                assert_eq!(execution.tool_name, "task_list");
                assert!(descriptor.label.contains("Ask for agent list"));
                approvals.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                Ok(false)
            },
        )
        .unwrap();
        server.join().unwrap();

        assert_eq!(
            approvals.load(std::sync::atomic::Ordering::SeqCst),
            1,
            "hook allow and FullAccess must still reach the native ask gate"
        );
        assert!(response.contexts.iter().any(|context| matches!(
            context,
            ContextItem::System {
                content,
                hook_execution: Some(metadata),
                ..
            } if metadata.event == "PermissionRequest"
                && metadata.status == "succeeded"
                && content.contains("\"behavior\":\"allow\"")
        )));
        assert!(response.contexts.iter().any(|context| matches!(
            context,
            ContextItem::Tool {
                tool_name,
                result,
                ..
            } if tool_name == "task_list"
                && !result.success
                && result.output.contains("The user denied the confirmation required by the hook.")
        )));
    }

    #[test]
    fn permission_hook_interrupt_rejects_parallel_calls_without_post_tool_or_native_approval() {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = serve_json_sequence(
            listener,
            vec![json!({
                "model": "model-test",
                "status": "completed",
                "output": [
                    {
                        "type":"function_call",
                        "status":"completed",
                        "call_id":"call-agent-list-denied",
                        "name":"task_list",
                        "arguments":"{}"
                    },
                    {
                        "type":"function_call",
                        "status":"completed",
                        "call_id":"call-agent-list-interrupted",
                        "name":"task_list",
                        "arguments":"{}"
                    }
                ],
                "usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}
            })],
        );

        let workspace = tempfile::tempdir().unwrap();
        let mut request = loop_request_for(address, workspace.path());
        request.security_level = SecurityLevel::FullAccess;
        #[cfg(windows)]
        let ask_command =
            r#"'{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"ask"}}'"#;
        #[cfg(not(windows))]
        let ask_command = r#"printf '%s' '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"ask"}}'"#;
        #[cfg(windows)]
        let deny_command = r#"'{"hookSpecificOutput":{"hookEventName":"PermissionRequest","decision":{"behavior":"deny","message":"permission hook denied this call","interrupt":true}}}'"#;
        #[cfg(not(windows))]
        let deny_command = r#"printf '%s' '{"hookSpecificOutput":{"hookEventName":"PermissionRequest","decision":{"behavior":"deny","message":"permission hook denied this call","interrupt":true}}}'"#;
        #[cfg(windows)]
        let post_command = "'post hook unexpectedly ran'";
        #[cfg(not(windows))]
        let post_command = "printf '%s' 'post hook unexpectedly ran'";
        request.active_hooks = vec![
            HookDefinition {
                id: "ask-agent-list".into(),
                name: "Ask for agent list".into(),
                event: HookEvent::PreToolUse,
                matcher: Some("^task_list$".into()),
                command: ask_command.into(),
                command_windows: None,
                status_message: None,
                enabled: true,
                timeout_ms: 5_000,
            },
            HookDefinition {
                id: "deny-and-interrupt-agent-list".into(),
                name: "Deny and interrupt agent list".into(),
                event: HookEvent::PermissionRequest,
                matcher: Some("^task_list$".into()),
                command: deny_command.into(),
                command_windows: None,
                status_message: None,
                enabled: true,
                timeout_ms: 5_000,
            },
            HookDefinition {
                id: "observe-post-agent-list".into(),
                name: "Observe post agent list".into(),
                event: HookEvent::PostToolUse,
                matcher: Some("^task_list$".into()),
                command: post_command.into(),
                command_windows: None,
                status_message: None,
                enabled: true,
                timeout_ms: 5_000,
            },
        ];

        let approvals = std::sync::atomic::AtomicUsize::new(0);
        let events = Mutex::new(Vec::new());
        let sink = |event| {
            events.lock().unwrap().push(event);
            Ok(())
        };
        let response = run_model(request, &AppState::default(), &sink, &|_, _, _| {
            approvals.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            Ok(true)
        })
        .unwrap();
        let captured = server.join().unwrap();

        assert_eq!(response.stop_reason.as_deref(), Some("hook_stopped"));
        assert_eq!(
            approvals.load(std::sync::atomic::Ordering::SeqCst),
            0,
            "a denying PermissionRequest hook must bypass native approval"
        );
        assert_eq!(
            captured.len(),
            1,
            "an interrupting permission denial must stop before another provider request"
        );

        let tool_results = response
            .contexts
            .iter()
            .filter_map(|context| match context {
                ContextItem::Tool {
                    tool_name, result, ..
                } if tool_name == "task_list" => Some((result.success, result.output.clone())),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            tool_results,
            vec![
                (false, "permission hook denied this call".into()),
                (false, "A hook interrupted this turn; this call was not executed".into())
            ],
            "both provider calls must retain an ordered tool result"
        );

        let events = events.lock().unwrap();
        let completed = events
            .iter()
            .filter_map(|event| match event {
                ModelStreamEvent::ToolExecutionCompleted {
                    call_id, result, ..
                } => Some((call_id.clone(), result.success, result.output.clone())),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            completed,
            vec![
                (
                    "call-agent-list-denied".into(),
                    false,
                    "permission hook denied this call".into()
                ),
                (
                    "call-agent-list-interrupted".into(),
                    false,
                    "A hook interrupted this turn; this call was not executed".into()
                )
            ],
            "each parallel provider call id must receive its own terminal result"
        );
        assert!(
            !events.iter().any(|event| matches!(
                event,
                ModelStreamEvent::HookExecutionStarted { event, .. }
                    if event == "PostToolUse"
            )),
            "PostToolUse must not run for a call rejected before execution"
        );
    }

