    #[test]
    fn dangerous_model_tools_honor_per_call_approval_and_denial() {
        let directory = tempfile::tempdir().unwrap();
        let mut request = run_request(ProviderFamily::OpenaiResponses);
        request.workspace_path = directory.path().to_string_lossy().into_owned();
        request.app_data_path = directory.path().to_string_lossy().into_owned();
        request.tools = catalog::tool_catalog();
        request.enabled_tools = request.tools.iter().map(|tool| tool.name.clone()).collect();

        let denied = execute_model_tool(
            &request,
            ToolCall {
                id: "call-denied".into(),
                name: "write".into(),
                input: Map::from_iter([
                    ("path".into(), json!("denied.txt")),
                    ("content".into(), json!("must not exist")),
                ]),
            },
            &AppState::default(),
            &|_, _, _| Ok(false),
            false,
        );
        assert!(!denied.result.success);
        assert!(denied
            .result
            .output
            .contains("The user declined this tool call"));
        assert!(!directory.path().join("denied.txt").exists());

        let approved = execute_model_tool(
            &request,
            ToolCall {
                id: "call-approved".into(),
                name: "write".into(),
                input: Map::from_iter([
                    ("path".into(), json!("approved.txt")),
                    ("content".into(), json!("written after approval")),
                ]),
            },
            &AppState::default(),
            &|tool_request, descriptor, _| {
                assert_eq!(tool_request.workspace_path, request.workspace_path);
                assert_eq!(descriptor.name, "write");
                assert_eq!(tool_request.input["path"], "approved.txt");
                Ok(true)
            },
            false,
        );
        assert!(approved.result.success);
        assert_eq!(
            std::fs::read_to_string(directory.path().join("approved.txt")).unwrap(),
            "written after approval"
        );
    }

